window.BIRYEONG_DATA = {"generatedFrom":"systems/vault (초록동색 C.01 콘텐츠 보관고)","rules":{"statKeys":["insight","aggression","endurance","control","agility","comprehension"],"stats":{"insight":{"label":"안목","en":"Insight","hint":"위험 감지 · 희귀(특수) 아이템 발견","detail":"위험 감지력과 희귀 아이템(특수 아이템) 발견 가능성이 올라간다."},"aggression":{"label":"호전","en":"Aggression","hint":"공격력 · 상대 파악 · 다이스 보정","detail":"공격력, 상대 파악, 다이스 전투 보정치가 올라간다. 단, 너무 높으면 선택지에서 돌발 행동 확률이 늘어난다."},"endurance":{"label":"인내","en":"Endurance","hint":"정신력 · HP 0에서 버틸 확률","detail":"정신력. 무언가를 버텨내거나 HP가 0일 때 버텨낼 확률이 높아진다."},"control":{"label":"절제","en":"Control","hint":"체력/영력/의지력의 활용이 효율적으로 변한다.","detail":"체력/영력/의지력의 활용이 효율적으로 변한다."},"agility":{"label":"신속","en":"Agility","hint":"수련 · 채집 속도","detail":"전체적으로 수련과 채집의 속도가 빨라진다."},"comprehension":{"label":"이해","en":"Comprehension","hint":"NPC 소통 · 호감도 · 돌발 전투 회피","detail":"NPC와의 소통, 호감도 상승량, 길거리 돌발 전투 회피율이 올라간다."}},"statMin":1,"statMax":50,"startPoints":10,"hpMax":100,"mpMax":100,"spiritStart":100,"spiritMax":500,"startMoney":50,"nameMax":12,"introMax":30},"zones":{"north":{"title":"산문","tabs":[]},"east":{"title":"강학당","tabs":[{"id":"mainHall","name":"본관","hanja":"靑","sections":[{"id":"intro","title":"둘러보기","kind":"text","paras":["사당을 중심으로 동쪽에 놓인 건물. 파란 띠가 둘러진 장승이 향하는 길목에 놓여있다. 학생들이 많이 들락날락하는 샛길을 따라 풀이 깎여있다. 짓밟힌 민들레는 무슨 일이 있었냐는 듯 다시 고개를 들어 자리를 잡는다. ……선생님과 교육자들을 포함하여 가장 많은 무속인들이 모여있는 만큼, 이런 불가사의한 현상이 비일비재하게 일어난다.","본관 벽의 모든 모서리에는 파란 글귀가 가지런히 적혀있다. 비상 시에 방벽으로 작용할 수 있게끔 만든 수식으로, 달에 한 번씩 선생님들이 이를 수리한다. 매 졸업생은 졸업 직전 글귀를 한 차례 수정하는 것을 졸업 요건으로 삼는다."]},{"id":"lessons","title":"수업","kind":"list","intro":"플레이는 몇 번이든 할 수 있고, 보상(영력)은 하루 한 번. 최소 점수를 넘긴 뒤 30분을 기다리면 받는다.","play":{"to":"lesson","label":"수업 고르기"},"items":[{"play":{"to":"lesson/talisman-2048","label":"2048 시작"},"name":"부적학","sub":"2048","desc":"수를 적재하여 부적의 기초적인 형태부터 심오한 형상까지 덧대어 그려보자. 단, 부적의 칸이 한정되어 있음을 잊지 말자.","lines":["부적의 나열을 가지런히 하여 수를 끌어올려보자.","통과 기준: 3000점 넘기기","주간 랭킹 과목"]},{"play":{"to":"lesson/spell-typing","label":"타자 시작"},"name":"주술학","sub":"타자","desc":"단어나 획 하나 잘못 그려져도 다른 형상으로 주술이 튀는 만큼, 반복해서 글자를 적어나가며 정확도를 올리자.","lines":["끊어진 부분이 없게끔 주문을 이어 적어보자.","통과 기준: 300타 넘기기","주간 랭킹 과목"]},{"play":{"to":"lesson/ward-tetris","label":"테트리스 시작"},"name":"결계학","sub":"테트리스","desc":"뿌리가 엉성하면 줄기도 부실한 법, 직접 결계 조각을 짜맞추며 어느 형상이 어떤 조각과 조화롭게 들어맞나 확인하자.","lines":["결계의 주춧돌을 직접 놓아보며 감을 익혀보자.","통과 기준: 5000점 넘기기","주간 랭킹 과목"]},{"play":{"to":"lesson/folklore-spot","label":"화투 신경쇠약 시작"},"name":"민속학","sub":"화투 신경쇠약","desc":"바깥 세상이나 여기나 암기가 중요하다는 건 변하지 않는다. 같은 그림이 그려진 카드를 골라 곧장 건져내보자.","lines":["똑같은 쌍의 상징물을 골라내며 기억을 시험해보자.","통과 기준: 3판 완료하기","주간 랭킹 과목"]},{"play":{"to":"lesson/divination-fortune","label":"운세 시작"},"name":"점복학","sub":"운세","desc":"원이라는 기초적인 시작에 맞춰 이를 불려나가며 운세를 어디까지 인간인 우리가 조정할 수 있는 지 시험을 해보자.","lines":["구슬을 맞춰 그곳에 반사된 상을 건져내보자.","통과 기준: 운세를 뽑기만 하면 완료"]},{"play":{"to":"lesson/exorcism-space","label":"달리기 시작"},"name":"퇴마실습","sub":"달리기","desc":"장애물을 뛰어넘고 고개를 숙이며 눈이 인식함과 동시에 몸이 곧장 움직여지게끔 팽이를 선 위에 올려 돌려보자.","lines":["어디까지 뛰어나갈 수 있는 지 자신을 한계에 몰아보자.","통과 기준: 5000점 넘기기","주간 랭킹 과목"]}]},{"id":"explore","title":"본관 탐사","kind":"scene","root":{"id":"explore","name":"본관","choices":[{"id":"b1","name":"지하 1층","text":[{"t":"지하 특유의 건조한 이끼 내음이 코를 찌른다. 그보다도 더 지독한 건 피부를 찌르는 냉기이다. 가끔가다 지하에 다녀오기 싫다고 툴툴거리던 선생님들의 모습이 눈 앞에서 아른거린다…. 복도에 걸린 나무 명패엔 **문헌보관소**, **비품실**이란 글자가 적혀있다. 저기로 이동하거나, 어떤 명패도 걸려있지 않고, 그저 복도 끝에 자리 잡은 **거대한 문**으로 다가갈 수 있어보인다."}],"choices":[{"id":"archiveB","name":"문헌보관소","text":[{"t":"지하에 놓인 문헌보관소. 1층에 있는 곳과 연결이 된다. 기운이 날뛰어서 함부로 지상에 두면 안 된다 여겨지는 서적들이 모여있는 곳으로, 아니나 다를까 **금줄과 흰 천**이 곳곳에 덮여있다. 몇몇 책은 애초에 제목도 확인할 수 없게끔 가려져 있다.  ...문헌보관소 **안내 수칙**을 한 번 살펴봐야 할 것 같다."}],"choices":[{"id":"rules","name":"안내수칙","text":[{"t":"금박이 박힌 종이가 코팅이 된 채로 문헌보관소의 문 옆에 붙어 있다. 쉽게 떨어지지 않게끔 모든 모서리에 청테이프가 덧대어져 있으며, 내용은 아래와 같다.\n\n1. 결코 혼자서 진입하지 마시길 바랍니다. \n2. 승인 받지 못한 접근은 불허합니다, 0번 항목을 참고 하시길 바랍니다.\n3. 도깨비불이 얹어진 등불을 지참한 후 진입하는 것을 권고합니다.\n\n⋯그러나 눈 씻고 보아도 그 어디에도 0번 항목이 보이지 않고 느껴지지도 않는다. 사당의 표지판과 같은 까닭인 걸까? 아직은 문헌보관소로 진입하는 게 어려워보인다."},{"t":"생각해보면 제법 괘씸한 감상이다. 도전하지 않거든 얻지도 못하는 법. 당신은 이대로 문을 힘으로 열어젖히고 싶다는 충동에 휩쓸린다. 하지만 당신에게 좋지 못한 일이 일어날 것 같다⋯⋯.","when":{"aggression":[15,null]},"mode":"append"},{"t":"자세히 보거든, 흐릿한 기호와 문자 같은 것이 안내문 위에서 일렁이는 것 같다. 이것을 붙잡아 자세히 읽어보려 시도한다면 저 너머의 것을 알아차릴 수 있을 것 같다. 하지만 당신에게 좋지 못한 일이 일어날 것 같다⋯⋯.","when":{"insight":[15,null]},"mode":"append"},{"t":"문득 이 문 앞에서 별의별 시도를 한 사람들이 많은 것 같다는 직감과 함께 아직 당신에겐 허락받지 못한 구역임을 알아차린다. 이 안에서 도사리고 있는 것은 학생 처지인 당신이 함부로 마주할 수 있는 게 아니다.\n\n‘더 많은’사람을 모아보거나 ‘도깨비불’ 에 대한 정보를 습득한다면 이 안으로 들어갈 수 있을 것 같다. 그런데 어디서, 어떻게? 그 부분은 시간이 해결해줄 부분인듯 하다.","when":{"control":[20,null]},"mode":"append"},{"t":"이 안에는 당신이 차마 이름을 부를 수도 없는 것이 갇혀있고 보관되어 있다. 인간은 신을 마주하는 것 만으로도 눈이 멀어버릴 수 있다는데, 당신이 무속 세계에 발을 담그고 있단 사실 하나 만으로 위력이 한 풀 꺾여서 닿는다. 소름이 목덜미를 타고 올라온다. \n\n느닷없이 시야 앞으로 푸른 불꽃이 휙 번지더니 옆으로 흐른다. 불꽃이 거대한 문에 달라붙어 꼼지락거리다가, 얼마 안 가서 그 안으로 몸을 밀어넣어 사라지고 만다.","when":{"comprehension":[15,null]},"mode":"append"}],"choices":[{"id":"force","name":"강제로 개봉한다","when":{"aggression":[15,null]},"result":["드드득 소리와 함께 문이 어거지로 열린다. 순간, 당신은 문헌보관소의 시꺼먼 창문이 ‘창문’이 아니라 내부의 존재였음을 알아차린다. 거뭇한 것이 그대로 당신 위로 쏟아져내린다. \n당신은 보관소 앞에 쓰러진 채로 고개를 들어올린다. 문은 굳건하게 닫혀있다. 당신은 환영받지 못했다."],"cost":{"mp":5,"wait":10}},{"id":"analyze","name":"분석한다","when":{"insight":[15,null]},"result":["이것은 글자를 받치는 종이가 아니라, 글자가 빼곡히 적힌 채로 만들어진 종이라는 사실을 알아차린다. 그제야 당신은 이 종이 자체가 하나의 문헌임을 알아차린다. 코를 타고 피가 주륵 흘러내린다. 이해한 것 만으로도 피로도가 쌓인다. 눈 앞이 가물가물 감긴다. \n당신은 보관소 앞에 쓰러진 채로 고개를 들어올린다. 문은 굳건하게 닫혀있다. 당신은 허락받지 못했다."],"cost":{"mp":5,"wait":10}}]},{"id":"cords","name":"금줄과 흰 천","text":[{"t":"무속 집안에 오래 몸 담고 있던 사람이었거나 아니라 하더라도 곧장 형태를 알아차린다. 이는 신과 같이 막강하고 이름이 강한 존재를 억지로 붙드는 매듭. 기리기 위함이고, 가리기 위함인 것. 당신은 반사적인 것에 가깝게 손을 맞댄 채로 기도를 올렸다. ⋯⋯. 문 안에서 나던 희미한 잡음이 사라진다. 불어올 리가 없는 따스한 바람이 당신을 스쳐 지나간다."}]}]},{"id":"supply","name":"비품실","text":[{"t":"설명문 자체는 오만가지 글귀와 부적을 덧대어 난잡해보이지만 열고 닫는 것을 돕는 **손잡이**만큼은 부드럽게 생겼다. 창문 너머로 내부를 엿보면 사물과 물건이 들썩거리며 이동하는 것 같다가도, 눈 깜빡. 하면 언제 그랬냐는 듯 얌전히 자리를 지키고 있다. 옆에 놓인 **비품실 안내사항**이 제법 살벌해보인다…."}],"choices":[{"id":"handle","name":"손잡이","text":[{"t":"푹신해보이는 장식이 덧대어진 손잡이를 잡으려고 드는 순간, 당신은 등골을 타고 올라오는 소름에 동작을 그치고 만다. 이 문을 열어선 안 된다는 강한 직감이 당신을 잡아 당긴다."}]},{"id":"notice","name":"비품실 안내사항","text":[{"t":"비품실에 들어설 때는 반드시 마음가짐을 경건히 하고 안의 물건들을 함부로 다루지 않으며 혹여나 빌린 물건을 돌려놓지 못할 때에는 교무실 또는 양호실에 가서 선생님을 찾으세요. 제를 올려야 합니다. 제를 올리는 이유는 비품실에 있는 모든 물건들이 "}],"after":"초상났네초상났어줄초상이났네떠나간님은오지않고오실님은소식이없고일어날일은벌어지지않고혼과백이뒤집히고천지가혼란하여온세상초상났네이세상은저세상이되어가고저세상은이세상이되어가니발이닿는곳마다곡소리끝없어꺼이꺼이하는소리숨넘는소리고개넘는소리바로그소리"}]},{"id":"escape","name":"거대한 문","text":[{"t":"삐걱거리는 낡은 문. 툭 치면 그대로 열릴 것 같이 생겼으나, 가까이 다가서면 다가설수록 크기가 거대해진다.. 눈을 몇 번 깜빡이면 들어오는 건 주변에 덕지덕지 붙은 공간 왜곡과 시각 왜곡 주술과 진들이다. 어디로 이어지는 걸까?"},{"t":"당신은 문 너머에서 푸른 불꽃이 일렁이는 걸 확인한다. 열기가 나갔다 사라진 탓에 달궈진 자물쇠가 헐거워보인다. 손을 대기도 전에 열이 식더니 다시 굳건하게 문을 붙든다.","when":{"comprehension":[15,null]},"mode":"append"},{"t":"이 문을 열어버릴 수 있을 것 같다. 적당한 힘과 적당한 협업이 가능하다면 그대로 부술 수 있을 것 같단 확신이 뇌리에 꽂힌다. 당신과 비슷한 처지의 사람들을 찾아봐야 할 것 같다.","when":{"insight":[20,null]},"mode":"append"}],"note":"별관 혹은 뒷산으로 이어진다."}]},{"id":"f1","name":"1층","text":[{"t":"본관 1층. 나무문 안쪽에 자리잡은 거대한 **로비**는 바닥과 천장에 독특한 문양이 번져있으며, 연꽃향이 은은하게 벽에서 난다. 방벽의 본관 아니랄까봐 입장과 동시에 어깨에 들어간 **긴장이 풀리는 기분**이다."},{"t":"한참 가만히 선 채로 본관 1층의 광경을 바라보다 보면, 로비의 중앙의 바닥이 천이라도 된 양 옆으로 스르륵 풀리더니 아래로 가는 계단이 드러난다. 사람들이 오간 흔적이 있는 것으로 보아, 비밀 입구는 아닌 모양이다. 본관의 **지하 1층**으로 향할 수 있다. 서늘한 공기가 계단을 타고 올라온다.","when":{"insight":[5,null],"control":[5,null]},"mode":"append"}],"choices":[{"id":"lobby","name":"로비","text":[{"t":"본관 1층은 사람의 이동이 잦은 만큼 문이 닫혀있을 때가 드물다. 활짝 열려있는 **나무문**을 통해 바람이 불어온다. 열린 문 저 너머, 정면에 놓인 황금색 기와 얹어진 **사당**이 눈에 닿는다. 고개를 돌리면 **교장실, 상장 거치대, 문헌보관소**가 언제나처럼 사람의 손길을 기다리며 놓여있다."}],"choices":[{"id":"woodDoor","name":"나무문","text":[{"t":"로비에 서있는 당신은 오방색으로 무늬가 수놓아진 나무문, 그쪽으로 걸어가길 택했다. 한 걸음 나가면 바깥 세상이라는 확신이 든다. 푸른 방벽 안에 있는 이상 당신은 현실의 것을 모른 채 살아갈 수 있다. …동시에, 나무문 안에 있는 한 당신은 그 현실의 것을 직시해야만 할 것이다. 뒤돌아서서 **로비**로 돌아가거나 **바깥**으로 나아갈 수 있다."}]},{"id":"shrine","name":"사당","text":[{"t":"조명과 무관하게 빛을 흡수하여 빛나는 기왓장 아래로 잿물을 먹인 나무가 단단하게 천장을 지탱하고 있는 사당. 보기만 해도 어딘가 섬뜩하다. 선생님들은 이를 아직 어리숙해서 그런 것이라 표현했으나, 당신은 그것만이 전부가 아닐 것 같음을 확신한다…."},{"t":"열린 문의 바깥, 저 멀리 중앙에 놓인 사당에 선 누군가가 당신을 향해 이리로 오라고 손짓했다. ……본능에 가깝게 고개를 휙 돌려버렸다. 귓가를 파고 드는 날카로운 종 소리와 함께 **나무문**이 닫힌다. 당신은 **로비**에 남겨졌다.","when":{"control":[null,9]},"mode":"append"},{"t":"열린 문의 바깥, 저 멀리 중앙에 놓인 사당에 선 누군가가 당신을 향해 이리로 오라고 손짓했으나, 당신은 다가가는 대신 손을 흔들어 인사하길 택했다. 무언가에 홀린듯 행동을 마친 뒤에 귓가에 닿는 문장은, *아직은 어리구나 아해야. 더 자라나 돌아오도록 하렴….* 앳된 존재의 목소리다. **나무문**이 천천히 닫힌다. 당신은 **로비**에 남겨졌다.","when":{"control":[10,null]},"mode":"append"}]},{"id":"calm","name":"긴장이 풀리는 기분","text":[{"t":"주술이라도 걸린 걸까, 아니면 바깥의 혼란으로부터 가장 안전함을 알아서일까? 안심이 되는 기분이다. 손에 들어간 긴장이 풀린다. 지나가는 선생님이 당신에게 깍듯하게 인사하고 지나간다."},{"t":"주술이라도 걸린 걸까. 당신은 고개를 들어 천장을 바라본다. 그곳에 그려진 문양이 바닥에 놓인 것과 일치함을 알아차린다. 그리고 그 문양이 당신이 언젠가 도서관에서 발견한 서적에 놓인 금기시된 술법의 진과 비슷하다는 점도. …긴장하라고 외치는 뇌와 달리 몸은 편안해진다.","when":{"insight":[10,null]},"mode":"replace"},{"t":"무구를 단단하게 붙잡고 있던 손에 힘이 훅 풀리고 만다. 바닥에 쩡 하고 뭔가 닿는 소리가 난 뒤에야 당신은 알아차린다. 무구가 떨어진 곳을 기점으로 만들어진 빛무리의 원은 주술 문장을 만들며 일렁이다가 바닥으로 흡수되어 사라진다. ⋯빛이 사라진 바닥엔 흠집 하나 안 남아있다.","when":{"aggression":[10,null]},"mode":"append"}]}]},{"id":"principal","name":"교장실","text":[{"t":"교장실의 문은 반쯤 열려있으나 이곳으로 함부로 들어서는 학생은 손에 꼽힐 정도다. 사실상 빈 장소에 가까움에도 선생님들조차 함부로 들어서지 못하는데, 이유야 간단하다. 아이들의 교육에 있어 가장 힘을 쓰는 게 마땅하지 않냐며 주장한 이가 이 학교의 설립자이자 현 교장이며, 동시에 한국 종교계에서 가장 힘이 큰 사람인 탓이다."}]},{"id":"awards","name":"상장 거치대","text":[{"t":"상장 거치대. 당장 우리 바깥에서 너 제정신이냐 아니냐 손가락질 듣고 있는데 이게 무슨 상장이냐고? 별 건 아니고 국가에서 제공해온, 그리고 앞으로 더 받게 될 상장 모음소이다. 해봤자 2000년대 초반의 것이 가장 오래 된 상장이다. 중간중간 체육부문 트로피가 보이는데… 문득, 무술 수련하는 친구들이 민간인 대회에 나가 상을 받아오곤 한다는 사실이 떠올랐다."}],"choices":[{"id":"awardOpen","name":"상장을 열람한다.","text":[{"t":"안녕하세요! 저는 게임의 제작자 팬케이크/마에입니다. 게임에 도움을 주신 분들께 감사의 표시를 드리기 위해 이 상장을 전합니다.\n\n[헌정 페어] 초록동색 - Terrarium(바리 에스티아, 에네시다오네 에스티아, 카르멘 가르시아, 막시밀리안 가르시아)\n[스토리 기반] 박신아 \n[운영 총괄 및 시스템] 바리\n[NPC 포트레이트] 오단애\n[아이템] 강유민\n[신수 도트 및 전투 밸런싱 전반] 금유성 \n[Special Thanks to…] 서문휘솔, 김미정\n[결계학 괴물 부문] 이청한"}],"choices":[{"id":"awardClose","name":"상장을 닫는다.","text":[{"t":"당신은 문득 코 끝을 누르고 지나가는 녹음, 귓가에 닿는 타닥이는 불티와 몸을 건드리고 지나가는 서늘하고 건조한 가을의 바람을 느낀다. 일상과 미지의 경계에 선 우리들은 때때로 신의 사랑을 받는다. 그것이 ‘끔찍한’ 방향일 때가 있어 곤란하기도 하지만⋯⋯. \n\n어떤 존재가 나의 안전과 행복을 바란다는 사실 하나 만으로 당신의 마음이 편안해진다."}]}]}]},{"id":"archiveG","name":"문헌보관소(1층)","text":[{"t":"각종 문헌이 보관되어 있는 장소. 별관 3층의 자료실과는 다른 기능을 하는 곳으로, 일반적인 서적보단 기록이나 통계에 가까운 책들이 모여있다. 지하 1층에는 당신의 나이 몇 배나 되는 고서적도 있다고 한다. 음기가 있는 곳에 놓여 있어야 그나마 기운이 눌러지는 책들이 있다나 뭐라나. 사서를 맡고 있는 **목조 조각상**이 달칵거리면서 망가진 책을 수선하고 있다."}],"choices":[{"id":"statue","name":"목조 조각상","text":[{"t":"책에 관련해 물어보지 않으면 말조차 섞어주지 않는 깐깐한 조각상이다. 당신의 방향을 잠깐 쳐다보지조차 않고 책을 묵묵히 수리하고 있을 뿐이다."}]},{"id":"shelf1","name":"책장1","text":[{"t":"알아볼 수 없는 책들이 가득하다. 언젠가 이 안을 뒤적여볼 때도 올까?"}]},{"id":"shelf2","name":"책장2","text":[{"t":"한자로 가득한 책들이 가득하다. 언젠가 이 안을 뒤적여볼 때도 올까?"}]},{"id":"shelf3","name":"책장3","text":[{"t":"어마어마하게 쌓인 책들이 가득하다. 언젠가 이 안을 뒤적여볼 때도 올까?"}]}]}]},{"id":"f2","name":"2층","choices":[{"id":"av","name":"시청각실","text":[{"t":"어두운 실내에 커다란 스크린이 걸려 있다. 책상 아래로 케이블이 얽혀 있고, 맨 뒷자리에는 누군가 두고 간 필기장이 있다. 전원을 켜자 기계가 낮게 웅웅거린다. 평범해 보이는 공간이지만, 귀신들도 나름 현대 문물이라는 것에 적응을 하기 때문에 저 네모난 스크린 안에서도 언제 어디서 무엇이 튀어나올지 모르는 법이다."}]},{"id":"beasts","name":"신수보관소","text":[{"t":"크고 작은 우리가 놓인 방에서는 풀 냄새와 낮은 숨소리가 섞여 나온다. 보관소라는 단어는 무기질적이다. 신수는 생명력이 넘친다. 둘은 서로 맞물리지 않는 듯 보이지만, 실제로 발을 들이고 나면 둘이 얼마나 잘 어울리는지 알게 될 것이다. 이 안에 있는 것들은 오직 사라지고 잊혀지고 죽은 존재들 뿐이니까."},{"t":"어디선가 어떤 소리가 들렸다. 무슨 소리지? 무슨 소리가 들렸다. 어떤 소음이지? 어떤 소음이 들렸다. 웬 소란이지? 웬 소란이 들렸다. 당신의 귀를 사로잡는 그 모든 것들이 당신을 현혹시킨다. 당신은 이러지도 저러지도 못하고 발걸음을 옮기고 빙글빙글 돌다가 밖으로 뛰쳐나왔다."}]},{"id":"staff","name":"교무실","text":[{"t":"영능력자인 학생들을 가르치는 선생님들 역시 그러할 것 같지만, 의외로 9할은 이론을 가르칠 수 있을 뿐인 주술사, 또는 신이 떠나 말문이 막힌 무당들 뿐이다. 졸업생들과 진짜 무당들은 어디에서 무엇을 하고 있을까? 그것은 아무도 모른다. 몇 안 되는 진짜 영능력자인 선생님들도 그들에 대해서는 함구한다."},{"t":"그들은 무언가를 알고 있다. 하지만 아무것도 말할 수 없는 듯 보인다. 그들이 입막음을 당한 것은 도대체 무엇일까. 그것이 정녕 당신들을 위한 것이 맞을까."}]},{"id":"nurse","name":"양호실","text":[{"t":"2층 끝의 방. 문턱을 넘으면 약초 달이는 냄새가 먼저 마중 나온다. 하얀 침대 몇 개와 낮은 약장, 창가에 말려 둔 쑥다발. 다친 학생이든 홀린 학생이든 일단 이곳에 눕혀 놓고 본다. 침대에 누우면 항상 양호실을 지키는 양호 선생이 고개를 내밀어 당신에게 인사해온다. 학교에 대한 것들을 묻거나, 지친 몸을 누일 수 있을 것 같다."}],"note":"양호 선생과 이야기하거나, 양호실로 가서 쉴 수 있다.","play":{"to":"rest","label":"양호실에서 쉬기"}},{"id":"meditation","name":"명상실","text":[{"t":"명상실이라고 적혀 있지만 다용도로 쓰이는 널따란 공간. 들어서면 마음이 평화롭게 안정되는 기분이 든다. 수업 중간중간 휴식을 위해 찾아온다곤 하지만, 본관에 제대로 된 침구나 담요 등이 준비되어 있는 곳은 여기뿐이기에 학생들 입에서는 ‘수면실’이라는 별칭으로 오르내리는 경우가 대부분이다."},{"t":"명상실은 본래는 두 개의 교실이었으나 붙어서 하나로 합쳐졌다고 한다. 이처럼 넓고 여유로운 공간인 데에는 까닭이 있었던 셈이다. 휴식을 위해 담요를 두르고 눈을 감은 순간 당신은 퍼뜩 눈을 다시 떴다. 누군가 어깨에 손을 얹은 듯한 기분이 들었다. 하지만 주변에는 아무도 없었다."}]}]},{"id":"f3","name":"3층","choices":[{"id":"class1","name":"교실(1학년)","text":[{"t":"첫 부적을 쓰고 첫 무구를 쥐는 학생들의 교실. 모든 것이 새로울 때라 실수도 많고 서투르지만 그만큼 생기와 활력이 도는 교실이다. 학생들의 양기가 넘치는 곳이라 되려 악의가 잘 침투하지 못하는 경우가 많다. 물론 한 번 침투한다면?"}],"choices":[{"id":"board1","name":"칠판","text":[{"t":"칠판 한편에는 정갈한 필기와 다음 시험 일정이 적혀 있다. 책상 아래로 수업 자료들이 산더미처럼 쌓여 있다. 낯선 수업의 긴장이 아직 사라지지 않은 교실의 공기 속에서도 아이들은 저만치서 조곤거리며 떠드느라 바쁘다."}]},{"id":"records1","name":"학생기록부","text":[{"t":"등록되어 있는 1학년 학생 전원의 명단이 보인다."}],"widgetNote":"이 기능은 아직 화면에 연결되지 않았다."}]},{"id":"class2","name":"교실(2학년)","text":[{"t":"1년간 온갖 산전수전을 다 겪었다고 생각한 아이들은 슬슬 착각하기 시작한다. 나는 이 세계에 대해 충분히 알게 되었다고. 방만과 방심이 끼어들면 저 세계의 적들은 이를 기민하게 알아차리고 접근해온다. 그러면 아이들은 현실에 대해 깨닫게 된다⋯⋯."}],"choices":[{"id":"board2","name":"칠판","text":[{"t":"칠판에서는 더 이상 장난의 흔적을 쉬이 찾아볼 수 없다. 딱딱하게 굳은 분위기를 풀려는 학생들도 몇은 있지만 대개는 현실을 정통으로 받아들이는 분위기다. 안전을 기원하는 부적 몇 개가 칠판 곳곳에 붙어 있다."}]},{"id":"records2","name":"학생기록부","text":[{"t":"등록되어 있는 2학년 학생 전원의 명단이 보인다."}],"widgetNote":"이 기능은 아직 화면에 연결되지 않았다."}]},{"id":"class3","name":"교실(3학년)","text":[{"t":"후배에게는 태연한 얼굴을 하겠지만 그 누구보다 앞길이 순탄치 않다는 것을 알고 있을 것이다. 지금까지 현실감을 깨닫지 못한 학생들은 진작 신병에 걸려 죽었거나 귀신에 씌여 학교를 떠났기 때문이다. 이 나이에 전학 온 늦깍이 학생이라면 모를까."}],"choices":[{"id":"board3","name":"칠판","text":[{"t":"사라졌던 낙서들이 다시 돌아왔다. 너무 경계하며 굳어봤자 먹잇감이 되기 쉬워진다는 것을 깨닫고 적절한 여유를 깨닫는 시기이다. 그것 또한 현실을 받아들이는 방법 중 하나일 것이다."}]},{"id":"records3","name":"학생기록부","text":[{"t":"등록되어 있는 3학년 학생 전원의 명단이 보인다."}],"widgetNote":"이 기능은 아직 화면에 연결되지 않았다."}]},{"id":"locker1","name":"물품보관소(1학년)","widgetNote":"이 기능은 아직 화면에 연결되지 않았다."},{"id":"locker2","name":"물품보관소(2학년)","widgetNote":"이 기능은 아직 화면에 연결되지 않았다."},{"id":"locker3","name":"물품보관소(3학년)","widgetNote":"이 기능은 아직 화면에 연결되지 않았다."},{"id":"storage","name":"본관 창고","text":[{"t":"잡동사니들이 쏟아지는 공간. 필요하다면 이 안에서 쓸만한 것들을 찾을 수 있을 것 같다. 하지만 낡은 물건들이 많은 만큼, ‘누군가’의 방해가 따르게 될지도 모르겠다는 예감이 든다. 굳이 방문할 필요가 없다면 괜히 건드리지 않는 게 좋을지도?"},{"t":"상당히 낡은 공간임에도 불구하고 벌레 한 마리 보이지 않는 기묘한 창고. 그 안에는 모든 것들이 강박적으로 정리되어 있다. 사람의 손을 타고 있다는 뜻임에도 불구하고 굳이 오래된 티를 벗지 않고 있으니, 분명 오래되어야 할 이유가 있음이라. 당신은 그 세월의 흔적들을 눈으로만 훑고 나왔다."}]}]},{"id":"roof","name":"옥상","text":[{"t":"이곳은 본래 정원이었다. 갈 곳 없는 자그마한 신이 이곳에 깃들어 이것저것 꾸미곤 했다. 그러나 그것도 옛말. 두 번째 *검은 안개*가 찾아오게 될 거라고 무속인들이 말을 모아 결론을 내릴 쯤 부터 그들 모두가 학교를 떠나고 말았다."}],"choices":[{"id":"door","name":"문","text":[{"t":"당신은 문 손잡이를 돌려 밀어본다. 순간 바람이 거세게 들이닥치며 쾅 하고 철문이 닫히는데, 그 틈 사이로 샛노란 눈이 보였던 것 같다."}]}]}]}},{"id":"infirmary","title":"양호실","kind":"text","paras":["2층 끝의 방. 문턱을 넘으면 약초 달이는 냄새가 먼저 마중 나온다. 하얀 침대 몇 개와 낮은 약장, 창가에 말려 둔 쑥다발. 다친 학생이든 홀린 학생이든 일단 이곳에 눕혀 놓고 본다. 침대에 누우면 항상 양호실을 지키는 양호 선생이 고개를 내밀어 당신에게 인사해온다. 학교에 대한 것들을 묻거나, 지친 몸을 누일 수 있을 것 같다.","휴식: 누워서 쉬기 / 선생님과 상담하기 — 1~120분, 1분에 1씩 회복."],"play":{"to":"rest","label":"양호실에서 쉬기"}}]},{"id":"annex","name":"별관","hanja":"白","sections":[{"id":"intro","title":"둘러보기","kind":"text","paras":["사당을 중심으로 서쪽에 놓인 건물. 별관의 하얀 건물은 푸른빛으로 일렁이는 본관과 대비가 될 정도로 하얗다. 모서리에는 글자 대신 동물 모양의 석상이 있으나, 목의 자리엔 그 무엇도 남아있지 않다. 자세히 보려고 해도 선생님들께선 그러는 것을 추천하지 않는다고 주의를 내릴 뿐이다.","가끔가다 내부와 외부의 공간이 다르게 느껴지거나 시간이 다르게 흐를 때가 있는데, 평범하게 홀렸거나 모시는 신들이 재주를 부린 것 뿐이니 너무 깊게 연연하진 말자. 애초에 피가 흐르고 눈물이 묻어도 다음 날이면 곧바로 무슨 일 있었냐는 듯 하얗게 탈색되는 벽과 바닥이 평범한 건물일 리는 없지 않은가?"]},{"id":"explore","title":"별관 탐사","kind":"scene","root":{"id":"explore","name":"별관","choices":[{"id":"f1","name":"1층","choices":[{"id":"auditorium","name":"강당","text":[{"t":"넓은 무대, 무대보다도 훨씬 넓은 강당이 이어져 있는 공간. 아무리 무속인들이라고 해도 대부분은 아직 철없는 학생들이라 한 번 행사라도 벌어지면 광란의 도가니가 된다. 선생님들은 대부분 어쩔 줄을 몰라한다. 쏟아지는 미친 양기에 그런 날은 귀신들도 어쩔 줄을 몰라한다."},{"t":"높은 천장 아래로 빈 의자들이 줄지어 놓였다. 무대 위에는 묵은 커튼이 드리워져 있다. 작정하고 꾸미는 날이 아닌 이상, 평소에는 으스스한 분위기를 준다. 불이 꺼져 있을 때에는 금상첨화로 무서운 분위기다. 누구 하나가 사라져도 모를지도? 농담."}]},{"id":"gym","name":"체력단련실","text":[{"t":"나무 바닥 위에 훈련용 도구가 가지런히 놓여 있다. 벽에 기대어 둔 무복에서는 땀과 세제 냄새가 엷게 난다. 한쪽 구석에는 ‘무복 좀 그날그날 빨아서 입고와 이 자식들아’ 라는 낙서가 붙어 있다. 무구보관소 담당의 글씨체인 것 같다."}],"note":"동아리 부실"}]},{"id":"f2","name":"2층","choices":[{"id":"craft","name":"공작소","text":[{"t":"책상마다 붓자국과 칼집이 남아 있다. 새 한지와 오색실, 다듬다 만 나무 조각이 손길을 기다린다. 굉장히 정교한 작업을 진행하는 곳이다 보니, 얼핏하면 손가락을 같이 날릴 생각이냐고 살벌한 타박을 듣는 일도 적지 않다."},{"t":"오랜 물건에 도깨비가 깃든다는 것은 유명한 전승이며, 실제로 일어나는 일이다. 대부분의 도깨비들은 이미 뒷산의 터에 모여 있지만 공작소의 물건들은 일부러라도 새로운 물건들로 항시 교체해두고 있다. 그들의 장난을 학생들이 수업 시간에 감당하는 건 불가능에 가깝기 때문이다."}],"note":"동아리 부실"},{"id":"music","name":"음악실","text":[{"t":"가락과 장단을 통해 마음과 영력을 다루는 음악실. 신을 부르는 소리와 친구를 부르는 소리가 한 공간에서 만난다. 본래부터 무속은 음악과 깊은 연관이 있었다고 하는데, 전승이란 것 자체가 음악을 통해 내려오는 것이니 그럴듯한 이야기일 것이다."},{"t":"피아노와 같은 현대적인 악기도 몇 가지 있지만, 대부분은 해금, 가야금, 꽹과리, 장구 등 다양한 전통 악기들이다. 이것들의 대부분은 들 수만 있다면 당장 무구로도 활용할 수 있는 악기들이기에 학생들 중 몇 명은 그대로 빌려 가서 퇴마 실습에 써먹어버리기도 한다."}],"note":"동아리 부실"},{"id":"board","name":"패 놀이터","text":[{"t":"패 하나에 희비가 명백히 교차하는 공간. 떠들썩한 목소리들이 공명하는 이 공간의 구석에는 구겨진 점수표며 손때가 묻은 화투, 엎어진 패가 잔뜩 놓여있다. 학생들의 정신건강에 좋지 않냐는 이야기가 주기적으로 나돌고 있다."},{"t":"웃어제끼는 목소리들 사이에 소름끼치는 웃음소리가 함께 들려왔던 것 같은 기분이 든다. 응? 윷놀이는 분명 네 명이서 하고 있지 않았던가? 방금 다섯이 들린 것 같기도? 기분 탓이겠지."}],"note":"동아리 부실"},{"id":"broadcast","name":"방송실","text":[{"t":"교내 방송과 비상 안내를 맡는 공간. 작은 마이크 하나가 수백 명의 하루를 바꿔 놓을 수도 있다. 그러니 언제나 대본을 볼 때는 주의해야 한다. 잘못 홀려 허튼 소리라도 한 번 하게 되었다간 만만찮은 책임을 지게 될 테니까."},{"t":"붉은 표시등이 꺼진 마이크가 책상 한가운데 놓여 있다. 녹음기 옆에 '방송 전에 확인'이라는 메모가 붙어 있다. 스피커에서 지직거리는 소리가 나자 괜히 등을 돌려 보게 된다."}],"note":"동아리 부실"},{"id":"cook","name":"조리실","text":[{"t":"따끈한 수증기가 창에 희미하게 맺혀 있다. 도마와 냄비가 깨끗하게 닦여 있고, 한쪽에는 만두를 빚다 남긴 밀가루 흔적이 있다. 냄새만으로도 배가 고파진다. 허기를 달래는 일도 수련이라면 이곳은 가장 인기 있는 수련장이다."},{"t":"식칼이며 프라이팬이며, 각종 조리도구들은 얼핏하면 사람을 해치는 도구들로 돌변하기 쉽다. 그러니 조리실을 사용하는 사람들은 출입을 할 때 ‘씌이지 않았음’을 확실히 증명해야 한다. 우스꽝스러운 몰골일지라도 그 위험성은 확실하기 때문이다."}],"note":"동아리 부실"}]},{"id":"f3","name":"3층","choices":[{"id":"books","name":"서적실","text":[{"t":"학생들이 읽을 책을 모아 둔 조용한 방. 교과서 외의 지식은 늘 조금 더 엉뚱한 곳에서 찾아오는 법이며, 그 대부분은 다소 사특하게 여겨지곤 한다. 사특하지 않게 느껴진다면, 단순히 운이 좋았던 것이다."},{"t":"책에 손때가 많이도 묻어 있다. 지금까지도 많은 학생들이 이 서적실을 오가며 종이를 팔락거렸을 것이다. 그 흔적을 고스란히 이곳에서 살펴볼 수 있다. 모르는 것은 찾고, 아는 것은 남겨보자."},{"t":"**책 에 서 당 장 손 떼**","chance":10}],"note":"동아리 부실"},{"id":"archive","name":"자료실","text":[{"t":"수업에 필요한 자료와 오래된 실습 기록을 보관하는 공간. 종이 위에서는 실패한 시도조차 다음 사람의 지도가 된다. 서랍마다 연도와 과목명이 붙어 있다."}],"choices":[{"id":"changnok","name":"창록고 (??%)","text":[{"t":"위장된 공립 기숙학교. 실제로는 무속 전승을 잇는 국립 기관이다. 특이한 건물 외형을 민간의 시선으로부터 가리기 위해 강원도의 산골 어딘가에 지어졌으며, 한반도 각지에서 사람들이 모이는 만큼 학생과 선생들의 옷차림이 계절마다 다양하다."}],"choices":[{"id":"history","name":"연혁","text":[{"t":"검은안개가 들이닥치기 전 부터 골조가 잡혀있었으나 학생들을 본격적으로 모집 하기 시작한 건 국가 단위로 법이 제정이 된 이후이다.\n1978년의 기록이 찢겨져 있고, 2000년 『무속·존속 유지법』에 대한 자료가 적혀 있다. 창록고등학교는 그와 동시에 강원도 강릉시 청화읍에 설립되었다고 적혀 있다. \n올해 26기수가 들어왔다."}]},{"id":"rules","name":"교칙","text":[{"t":"8이라는 숫자에 맞춰 기록되어 있다.\n1항. 창록고등학교에 소속된 모두는 무속 세계의 일원일 것. 민간인은 출입을 금한다.\n2항. 창록고등학교에 소속된 인간은 무속 세계에 헌신을 할 것.\n3항. 창록고등학교에 소속이 된 존재는 인간세계에 위해를 가하지 않을 것.\n4항. 외부에서 들어온 침입자가 있을 경우 민간인인 경우는 존재치 않기에 발견 시 자리에서 대피 후 다른 학우들에게 알릴 것.\n5항. 인간의 형체를 하지 않은 모든 것과 눈을 마주치지 말 것.\n6항. 악의가 느껴지지 않는 존재들의 기이한 부탁은 가능한 들어줄 것. 들어줄 수 없더라도 노력하는 성의를 보일 것.\n7항. 학교의 도깨비들에게 친절하게 대할 것.\n8항. **검은 안개**와 관련된 모든 것과 마주할 시 즉시 모든 활동을 정지하고 선생에게 알린 뒤 모든 학우들과 함께 본관 옥상으로 대피할 것."}]},{"id":"layout","name":"배치","text":[{"t":"본관-청, 별관-백, 기숙사-흑, 뒷산-적, 사당-황. \n방위와 제례가 겹친다. 각 색에 알맞은 모습으로 적절히 꾸며져 있다."}]}]},{"id":"fog","name":"검은 안개","text":[{"t":"검은 안개에 대해 자세히 기술하고 있는 서적은 전국에서 창록고 한 곳에만 모여 있다. 열람 시 이상한 기분이 들 경우 즉시 책을 닫은 후 바깥으로 나가 하늘을 향해 기도하는 것을 자료실 내부에서 권하고 있다."}],"choices":[{"id":"fogPreface","name":"[검은안개 생존자 구술록 : 1편 서문. 12p]","text":[{"t":"물이 역류하고 바람이 빙글거리며 돈다는 것이 이변의 상투적인 묘사로 변모한다. 거뭇한 구름이 한반도 전역을 뒤덮은 날에도 민간인들은 입을 모을 생각도 않은 채 가설과 방향성을 따지려 들었다. 그들이 그토록 아끼던 수치와 환산을 다뤄 통계와 분포를 만들거든 시발점과 끝날 지점을 얻을 수 있으리라 믿은 것이다.\n\n상식 바깥의 일을 상상해본 적이 있는가?\n상식이 바깥이 일이 되는 것을 떠올려본 적이 있긴 한가?\n사건과 사고가 즐비했음에도 그 시절에 대해 회고할 수 있는 이들은 몇 없다."}],"choices":[{"id":"fogCh4","name":"***[검은안개 생존자 구술록 : 1편 4장 아비규환 78p]***","text":[{"t":"*방울소리가 창문에 부딪혀 산산조각나면 들짐승이 짖을 법도 하거늘 사특한 것 마주하면 목청 터질 정도로 바락바락 소리지르던 것들 죄다 바닥에 고개를 처박는다. 닭은 해가 뜨질 않으니 우는 법 잊었고 닭 울지를 않으니 아이는 아침이 언제인지 모르며 아이가 잠에서 일어나지 않으니 어미는 자식을 잃은 줄 알아 슬픔에 먹히고 아비는 그들이 서러이 울어 집이 망가진 줄 알고 다급히 집으로 돌아오다 어둠 속에서 고꾸라지고 집 바깥에 나돌아다니던 행인들 전봇대와 누군가의 다리에 걸려 넘어지거나 그렇게 깨진 뒷통수와 코에서 줄줄 흐르는 피 누군가가 핥아먹고 가는데 얼마 안 가서 머리 어질어질 거리고 바닥으로 픽 쓰러지더니*"}],"fx":"jitter"}]}]}]},{"id":"tea","name":"다도실","text":[{"t":"다도 용품이 가지런히 갖춰진 다실. 뭔가 먹을 때 조용하지 않으면 돌연사하는 사람들이 주로 찾는 곳이다. 그런 강박이 모여 만들어진 곳이니만큼 무려 서적실과 자료실 옆에 자리하는 부실이 되는 영광을 누리게 되었는데, 사람 여럿이 모여 조곤조곤 차를 끓여도 소리가 튀는 법이 없었다. 시끄러우면 내쫓긴다."},{"t":"당신이 정신을 차렸을 때 당신은 이미 녹차 티백을 멍하니 한 손에 쥐고 있었다. 손에서 물이 뚝뚝 떨어진다."}],"note":"동아리 부실"}]},{"id":"roof","name":"옥상","text":[{"t":"별관은 본관과 달리 옥상이 잠겨 있지 않다. 오히려 너무 팍팍하게 굴지 말라는 듯 느슨하게 꾸며져 있고, 학생들의 손이 많이 닿도록 안배되어 있다. 마치 무언가를 경계하지 않음으로써 역으로 경계하듯이."}],"choices":[{"id":"garden","name":"정원","text":[{"t":"나비 한 마리가 꽃대를 따라 오르내린다. 평화로워 보이는 곳이지만, 한 때는 대피소로 쓰이기도 했던 곳이며 지금 역시도 긴급 대피 훈련을 할 때는 모두가 이곳으로 올라오는 것을 훈련받는다. 본관의 옥상은 잠겨서 열리지도 않는다는데, 이곳은 열려 있는 이유가 뭘까."},{"t":"이곳을 들락거릴 때에는 이유 모를 신기에 으스스한 소름이 돋곤 한다. 주변을 반사적으로 홱 돌아보면 아무것도 없는 공기만이 당신을 반기고 공허한 기분을 느낄 뿐이다."},{"t":"*이곳까지 쫓아온 무언가에게서 도망치려면 떨어지는 수밖에 없을까?*","chance":10}],"note":"동아리 부실"},{"id":"plaza","name":"옥상광장","text":[{"t":"발아래 넓은 바닥이 햇살을 받아 따뜻하다. 난간 너머로 청화강 쪽의 빛이 가늘게 비치며 바로 아래에서는 떠드는 학생들의 목소리가 드문드문 바람을 타고 흘러들어온다. 목소리가 큰 아이들에게 비밀은 없다. 그것은 비단 인간들에게만 흘러들어가지 않을 테니, 학생들은 주의하는 법을 배우는 것이 좋을지도 모른다."},{"t":"학생들은 옥상에 오르내리며 대피 훈련을 할 때면 가장 먼저 옥상 난간에 절대 기대지 말 것을 당부받는다. 절대로 가까이 가지도 말 것, 난간에 손도 대지 말 것, 피치 못하게 가까이 가더라도 결코 아래를 직접 내려다보지 말 것. 정신을 차려보니 그런 일이 일어났다─등의 사건이 일어나는 최악의 경우, *당신과 눈을 마주하고 있는 존재에게서 최대한 빠르게 눈을 돌릴 것.*"},{"t":"*이곳까지 쫓아온 무언가에게서 도망치려면 떨어지는 수밖에 없을까?*","chance":10}]}]}]}},{"id":"clubs","title":"동아리","kind":"list","items":[{"name":"무예 동아리","sub":"1층 · 체력단련실","desc":"유년시절을 근육으로 채우겠다는 의지가 가득찬 학생들이 주로 들어가는 동아리. 동아리 소속생을 대상으로 한 보조기기 대여와 무구 무료 점검이 특징이다.","lines":[]},{"name":"미술 동아리","sub":"2층 · 공작소","desc":"부적 적는 것에 지친 학생들이 평화의 돌파구를 얻기 위해 만든 동아리. 노란 종이와 붉은 염료는 부실에서 사용 금지이나, 교내의 주술 복구를 위해 가장 많이 불려나간다.","lines":[]},{"name":"음악 동아리","sub":"2층 · 음악실","desc":"귀에 달라붙는 소리를 떨쳐내기 위해 악기 다루는 법을 가르쳐 주는 동아리. 문제가 있다면 그들이 다루는 악기는 연주용 보다는 퇴마용이라, 전부 다 개성이 강하다.","lines":[]},{"name":"판놀이 동아리","sub":"2층 · 패 놀이터","desc":"어딜 가도 존재한다는 보드게임을 운 관련 동아리. 가끔가다 부실 앞에서 쫄깃쫄깃 털린 채로 엎드려 몸 파닥거리는 학생들이 발견되곤 한다.","lines":[]},{"name":"방송 동아리","sub":"2층 · 방송실","desc":"학교의 구색을 갖추기 위해 만들어진 장비가 죄다 새것인 동아리. 긴급 상황 시 대피와 탈출을 알리는 것들 또한 이 동아리 학생들의 몫이다.","lines":[]},{"name":"요리 동아리","sub":"2층 · 조리실","desc":"한창 자라나는 시기의 청소년에게 먹을 것의 자유를 주고자 만들어진 동아리. 베이킹, 돌판에 고기 굽기, 라드 모아서 김치 굽기. 뭐든 편향되지 않았냐고? 잘 먹으면 그만이다.","lines":[]},{"name":"독서 동아리","sub":"3층 · 서적실","desc":"의견을 나누고 어떻게든 생각을 발산하고픈 이들을 위한 동아리. 대체로 중구난방식으로 이루어지는 토론, 멋대로의 책 선정이나 떠들 수 있다는 사실 하나만으로 만족도가 높다.","lines":[]},{"name":"차 동아리","sub":"3층 · 다도실","desc":"외부에서 벗어나 잠깐이라도 쉬고픈 이들을 위해 창설이 된 동아리. 말을 나누고 말고는 전적으로 개인의 선택. 매 동아리 모임마다 부원들이 과자를 가져온다.","lines":[]},{"name":"원예 동아리","sub":"옥상 · 정원","desc":"","lines":[]}]},{"id":"workshop","title":"공작소","kind":"list","intro":"일반 고등학교의 미술실 대신 쓰는 시설이라 해도 좋을 정도로 다양한 도구가 준비되어 있는 공간. 이곳에서 재료를 합성해서 물건을 제작할 수 있다.","play":{"to":"workshop","label":"공작소에서 제작하기"},"items":[{"name":"무언가멋진천이꽂힌알코올램프","sub":"자투리 천조각 ×2 + 알코올 램프 ×1","desc":"어쩐지 병이 초록색이다. 제작자는 교무실로 오라고 하신다.","lines":["아이템 효과 없음. 만들면 [직업은 학생, 취미는 운동] 업적을 달성한다."]},{"name":"초보용 고독","sub":"들쥐 ×2 + 지네 ×2 + 작은 항아리 ×1","desc":"흉내를 냈을 뿐인 귀여운 수준이다. 이 정도는 대단한 저주라고 할 수도 없다. 이제까지의 한과 역사에 비교하면.","lines":["사용 시 3턴 동안 적이 받는 모든 피해량이 20% 증가한다."]},{"name":"고독","sub":"들쥐 ×5 + 지네 ×5 + 작은 항아리 ×1","desc":"살아남는 건 하나 뿐. 그렇게 겨우 살아남은 마음을 짓밟는 것으로 실현되는 저주가 있다. 그러나 주의해라. 업으로부터 달아날 수 있는 존재는 없다.","lines":["사용 시 [보스] 태그를 포함한 그 어떤 적이든 일격에 처치할 수 있다. 하지만 사용자와 주변인에게 매우 좋지 않은 일이 일어날 것 같다."]},{"name":"저주인형","sub":"절묘한 나무조각 ×5","desc":"무언가를 증오하는 흔하고-고전적이며-다소 목가적인 방식으로 유행조차도 타지 않는다! 그래도 친구에게는 사용하지 말자. 어떤 일들은 돌이킬 수 없으니까.","lines":["전투 중: 적의 영능력 자원(영력) -3 (한 전투에 1번)"]},{"name":"숫돌","sub":"바위 ×9","desc":"날을 세우는 데 쓰는 곱게 갈린 숫돌. 무구에 처음 손을 대는 사람이 가장 먼저 찾는다.","lines":["무구 일반 강화(1~3번째)와 특수 강화(화투패 1장 + 숫돌 9개)에 쓰는 재료."]},{"name":"연마석","sub":"숫돌 ×1 + 자갈돌 ×1","desc":"무구를 다듬을 때 쓰는 단단한 연마석.","lines":["무구 일반 강화에 쓰는 재료. n번째 강화에 n개가 든다 (마지막 15번째는 15개). 공작소에서 숫돌 1개 + 자갈돌 1개로 만든다."]},{"name":"오색 매듭","sub":"오색실 ×3","desc":"무구의 자루에 다는 오방색 매듭. 눈에 익은 장식이 쥔 사람의 마음가짐까지 가다듬는다.","lines":["무구보관소에서 무구를 일반 강화(7~9)할 때 쓰는 재료."]},{"name":"조개 목걸이","sub":"조개껍데기 ×3 + 노끈 ×1","desc":"알로하. …아, 이게 아니야?","lines":["착용 시 신속 +2 · 이해 +1, 개척 성공 확률 +5%p"]},{"name":"기름 먹인 천","sub":"콩기름 ×3 + 자투리 천조각 ×1","desc":"무구의 날과 자루를 닦아 윤을 내는 천. 손에 쥐는 맛이 달라진다.","lines":["무구보관소에서 무구를 일반 강화(4~6)할 때 쓰는 재료."]},{"name":"주사 호신부","sub":"붓 ×1 + 부적 조각 ×3 + 초승꽃 ×2 + 그믐꽃 ×2 + 주사 ×3","desc":"붉은 주사로 한 획 한 획 써 내린 작은 부적. 무구에 붙여 두면 쓰는 이의 기운이 한결 안정된다.","lines":["무구보관소에서 무구를 일반 강화(10~12)할 때 쓰는 재료."]},{"name":"깃털 장식","sub":"멧비둘기 깃털 ×3 + 오색실 ×1","desc":"언제까지나 차있는 둥지는 없다. 새들은 어디로 갔을까?","lines":["개척 중: 이번 개척 동안 추가 보상 확률 +12%"]},{"name":"장승 키링","sub":"조각칼 ×1 + 장승 조각 ×5","desc":"옛날에는 영험했던 것인지, 가지고 있으면 안전한 기분이 든다.","lines":["개척 중: 8턴 동안 요괴가 다가오지 못하고, 마주쳐도 비켜 간다"]},{"name":"녹색 부적","sub":"부적 조각 ×2 + 쑥 ×3","desc":"태우면 마음이 안정된다. 뒤에 산이 있는 만큼 화기를 사용할 때는 주의할 것","lines":["전투 중: 나의 나쁜 상태(독·저주·속박 등) 해제 / 의지력 +10"]},{"name":"네잎클로버 책갈피","sub":"한지 ×3 + 주머니 ×1 + 네잎클로버 ×1","desc":"가지고 있는 것만으로 행운을 가져다 줄 것 같은 책갈피.","lines":["개척 중: 다음 1번의 성공 보상이 2배"]},{"name":"재액부","sub":"고라니 이빨 ×2 + 한지 ×2 + 붓 ×1 + 먹 ×1","desc":"사람 같은 비명 소리가 난다. 사용시에는 귀를 막을 것. 귀를 막지 않았다면 양호실로 뛰어가자.","lines":["전투 중: 적의 영능력 자원(영력) -4 / 적의 앞으로 2개 행동을 간파 (한 전투에 1번)"]},{"name":"축귀문","sub":"뱀 허물 ×2 + 쑥 ×3","desc":"끔찍한 냄새가 난다. 이쪽으로 가까이 다가오기 싫을 정도로!","lines":["전투 중: 일행 전원의 나쁜 상태(독·저주·속박 등) 해제"]},{"name":"붉은여우 부적","sub":"부적 조각 ×2 + 여우 꼬리털 ×3 + 한지 ×3 + 오색실 ×1 + 장승 조각 ×1 + 먹 ×1 + 주머니 ×1","desc":"여우 꼬리털을 넣은 임시 부적. '다른 것'이 되는 기분을 느낄 수 있다.","lines":["전투 중: 전투 중 신속 +4 · 안목 +2 (다인 전투는 그 전투 동안, 단독 전투는 20분)"]},{"name":"일회용 수호령","sub":"너구리 발톱 ×3 + 장승 조각 ×3","desc":"보기엔 흉물스러운 경우가 많다. 진품과 가품 구분도 모호하기에 직접 만들어서 쓰는 걸 추천한다.","lines":["전투 중: 전투불능 시 1회 체력 1로 부활 대기(한 전투에 부활 아이템은 1번)"]},{"name":"도깨비 탈","sub":"장승 조각 ×2 + 절묘한 나무조각 ×2","desc":"야영지 지킴이가 쓰고 다니는 것과 같은 붉은 색의, 푸른 뿔이 달린 도깨비 탈. 얼굴을 가리는 것 외에도 어떤 것을 ‘받아들이는’ 효과를 주기도 한다.","lines":["착용 시 모든 공격력에 +200% 보정. 단, 돌발 확률이 50% 늘어나고, 아군을 일반 공격으로 공격할 확률이 (호전/3)% 생긴다."]},{"name":"오색실","sub":"거미줄 ×5 + 염색약 ×1","desc":"결계를 만드는 데 사용되는 재료. 삐끗하면 엉켜버린다.","lines":["제작용 재료"]},{"name":"한지","sub":"구겨진 한지 ×2","desc":"매끈하고 질긴 새 한지. 번지지 않아서 글씨 쓰기 좋다.","lines":["제작용 재료."]},{"name":"붓","sub":"갈라진 붓 ×2","desc":"털끝이 가지런한 평범한 붓. 부적이든 서예든, 일단 이게 있어야 시작이다.","lines":["제작용 재료."]},{"name":"소형 돌제단","sub":"바위 ×5 + 절묘한 나무조각 ×3","desc":"소원을 비는 제단으로 기능한다. 그리 효과가 좋진 않지만 없는 것보다는 낫다.","lines":["개척 중: 4턴 동안 요괴가 다가오지 못하고, 마주쳐도 비켜 간다"]},{"name":"노끈","sub":"칡 뿌리 ×3","desc":"칡뿌리 껍질을 비벼 꼰 질긴 끈. 묶을 수 있는 건 다 묶어 보고 싶어진다.","lines":["제작용 재료"]},{"name":"털실 뭉치","sub":"토끼 털뭉치 ×2 + 거미줄 ×2","desc":"토끼털과 거미줄을 함께 자아 만든 털실. 거미줄이 들어간 덕에 이상할 만큼 끊어지지 않는다.","lines":["제작용 재료"]},{"name":"송연묵","sub":"솔방울 ×4 + 물이끼 ×1","desc":"솔방울을 그을려 받은 그을음에 물이끼를 개어 굳힌 먹. 매점 먹보다 향이 훨씬 진하다.","lines":["제작용 재료"]},{"name":"붉은 꽃물","sub":"초승꽃 ×1 + 그믐꽃 ×1","desc":"초승꽃과 그믐꽃을 함께 짜낸 붉은 물. 굳기 전에 쓰지 않으면 꽃이 다시 오므라든 것처럼 거뭇해진다.","lines":["제작용 재료"]},{"name":"수정 구슬","sub":"수정 ×2 + 물이끼 ×2","desc":"수정을 물이끼로 문질러 둥글게 간 구슬. 들여다보면 내 얼굴이 거꾸로 비친다.","lines":["제작용 재료"]},{"name":"벽조목 패","sub":"벽조목 ×2 + 조각칼 ×1","desc":"벽조목을 조각칼로 다듬어 만든 손바닥만 한 패. 잡귀가 이 패만 보면 슬금슬금 피한다.","lines":["제작용 재료"]},{"name":"깃털 다발","sub":"멧비둘기 깃털 ×2 + 꿩 깃털 ×2","desc":"멧비둘기 깃과 꿩 깃을 가지런히 묶은 다발. 바람이 불면 혼자 날아가려 든다.","lines":["제작용 재료"]},{"name":"봉인 가루","sub":"봉인석 ×1 + 뼛조각 ×2","desc":"봉인석과 뼛조각을 함께 빻은 잿빛 가루. 손가락에 묻으면 한동안 감각이 둔해진다.","lines":["제작용 재료"]},{"name":"부적 먹물","sub":"송연묵 ×1 + 붉은 꽃물 ×1","desc":"송연묵을 붉은 꽃물에 갈아 낸 검붉은 먹물. 이걸로 쓴 획은 마르고 나서도 미묘하게 꿈틀거린다.","lines":["제작용 재료"]},{"name":"돌팔매 주머니","sub":"자갈돌 ×5 + 주머니 ×1","desc":"자갈돌을 잔뜩 넣은 주머니. 던지는 것보다 들고 다니는 게 더 힘들다.","lines":["전투 중: 적에게 막을 수 없는 피해 2d6 (적 체력은 1 아래로 내려가지 않는다 — 마무리는 직접) (한 전투에 1번)"]},{"name":"돌탑 모형","sub":"바위 ×3 + 자갈돌 ×3","desc":"산길의 돌탑을 흉내 내 쌓아 본 작은 탑. 마지막 돌을 올릴 때 숨을 참게 된다.","lines":["개척 중: 개척 행동 턴 +3"]},{"name":"부적 묶음","sub":"부적 조각 ×4 + 한지 ×1","desc":"바스러지기 직전의 부적 조각을 한지로 감싸 묶은 것. 효험은 반의반이라도 있는 게 낫다.","lines":["전투 중: 부적 사용 횟수 +1 (한 전투에 1번)"]},{"name":"뱀 허물 책갈피","sub":"뱀 허물 ×1 + 한지 ×2","desc":"반투명한 허물을 한지 사이에 눌러 말린 책갈피. 책을 펼 때마다 흠칫한다.","lines":["개척 중: 2턴 동안 동물·영물이 제자리에 멈춘다"]},{"name":"쑥 향","sub":"쑥 ×4 + 한지 ×1","desc":"쑥을 말려 한지로 돌돌 만 향. 피우면 잡귀보다 사람이 먼저 기침한다.","lines":["개척 중: 6턴 동안 요괴가 다가오지 못하고, 마주쳐도 비켜 간다"]},{"name":"지네 부적","sub":"지네 ×2 + 부적 조각 ×2 + 붓 ×1","desc":"지네 독으로 쓴 부적. 다른 벌레가 오지 않는 대신 이 부적을 만진 사람도 한동안 아무도 오지 않는다.","lines":["전투 중: 적에게 막을 수 없는 피해 3d6 + 4 (적 체력은 1 아래로 내려가지 않는다 — 마무리는 직접) (한 전투에 1번)"]},{"name":"물이끼 화분","sub":"물이끼 ×3 + 벽돌 ×1","desc":"벽돌을 파낸 자리에 물이끼를 심은 화분. 기숙사 창가에 두면 방이 조금 덜 건조해진다.","lines":["개척 중: 다음 3번의 채집·수렵 성공률 +15%"]},{"name":"송연묵 부적","sub":"송연묵 ×1 + 한지 ×2 + 붓 ×1","desc":"직접 만든 송연묵으로 쓴 부적. 매점 먹으로 쓴 것보다 글씨에 힘이 붙는다.","lines":["전투 중: 부적 사용 횟수 +1 / 의지력 +10 (한 전투에 1번)"]},{"name":"털실 인형","sub":"털실 뭉치 ×2 + 절묘한 나무조각 ×1","desc":"털실을 감아 만든 작은 인형. 이상하게 만든 사람을 닮는다.","lines":["개척 중: 3턴 동안 동물·영물이 제자리에 멈춘다"]},{"name":"오소리털 붓","sub":"오소리 털 ×2 + 절묘한 나무조각 ×1","desc":"오소리 털을 매어 만든 붓. 빳빳해서 부적 획이 끊기지 않는다.","lines":["전투 중: 부적 사용 횟수 +2 (한 전투에 1번)"]},{"name":"주사 인주","sub":"주사 ×2 + 물이끼 ×1","desc":"주사를 물이끼로 갠 붉은 인주. 도장을 찍으면 종이가 살짝 따뜻해진다.","lines":["전투 중: 전투 중 절제 +5 · 안목 +1 (다인 전투는 그 전투 동안, 단독 전투는 20분)"]},{"name":"도깨비불 등롱","sub":"도깨비불 ×1 + 한지 ×3 + 노끈 ×1","desc":"한지 등롱 속에 도깨비불을 가둬 노끈으로 매단 것. 기름이 필요 없는 대신 가끔 혼자 산책을 나간다.","lines":["개척 중: 개척 행동 턴 +5"]},{"name":"봉인 부적","sub":"봉인 가루 ×1 + 붉은 꽃물 ×1 + 한지 ×2","desc":"봉인 가루를 붉은 꽃물에 섞어 쓴 부적. 붙이는 순간 주변 공기가 한 겹 무거워진다.","lines":["전투 중: 적의 영능력 자원(영력) -8 / 적의 앞으로 1개 행동을 간파 (한 전투에 1번)"]},{"name":"이무기 비늘 호패","sub":"이무기 비늘 ×1 + 절묘한 나무조각 ×2","desc":"이무기 비늘을 박아 넣은 나무 호패. 물가에 가면 비늘이 저 혼자 파르르 떤다.","lines":["개척 중: 다음 5번의 채집·수렵 성공률 +25%"]},{"name":"늑대 송곳니 부적","sub":"늑대 송곳니 ×1 + 붉은 꽃물 ×1 + 부적 조각 ×2","desc":"늑대 송곳니에 붉은 꽃물로 주문을 새긴 부적. 밤길에 쥐고 있으면 뒤를 덜 돌아보게 된다.","lines":["전투 중: 적에게 막을 수 없는 피해 2d10 + 적 최대 체력의 3% (적 체력은 1 아래로 내려가지 않는다 — 마무리는 직접) / 전투 중 호전 +6 (다인 전투는 그 전투 동안, 단독 전투는 20분) (한 전투에 1번)"]},{"name":"벽조목 호부","sub":"벽조목 패 ×1 + 부적 먹물 ×1","desc":"벽조목 패에 부적 먹물로 수호 문자를 새긴 호부. 잡귀가 보면 먼 길을 돌아간다.","lines":["개척 중: 이 터를 떠도는 요괴를 쫓아낸다(보상 없음)"]},{"name":"매 깃털 깃펜","sub":"매 깃털 ×1 + 송연묵 ×1","desc":"매의 꼬리깃을 깎아 송연묵을 찍어 쓰는 깃펜. 글씨가 저절로 날렵해진다.","lines":["개척 중: 개척 행동 턴 +2 / 이번 개척 동안 안목 +6 · 신속 +6 · 이해 +4"]},{"name":"혼백 등불","sub":"혼백구슬 ×1 + 도깨비불 등롱 ×1","desc":"도깨비불 등롱 안에 혼백구슬을 넣은 등불. 불빛 아래에서는 그림자가 하나 더 생긴다.","lines":["개척 중: 개척 행동 턴 +10 / 4턴 동안 동물·영물이 제자리에 멈춘다"]},{"name":"황구렁이 비늘 함","sub":"황구렁이 비늘 ×1 + 벽조목 패 ×1","desc":"벽조목 패에 황구렁이 비늘을 덮어 짠 작은 함. 넣어 둔 것이 줄어들지 않는다는 소문이 있다.","lines":["개척 중: 다음 3번의 성공 보상이 2배 / 이번 개척 동안 추가 보상 확률 +15%"]},{"name":"오복 부적","sub":"오복 날개막 ×1 + 부적 먹물 ×1 + 한지 ×2","desc":"오복 날개막을 부적 먹물로 한지에 붙여 쓴 부적. 빛에 비추면 다섯 빛깔이 차례로 돈다.","lines":["전투 중: 일행 전원 그 전투 동안 모든 육조 +3 / 일행 전원 부적 사용 횟수 +1"]},{"name":"천년거북 점판","sub":"천년거북 등딱지 ×1 + 붉은 꽃물 ×1","desc":"천년거북 등딱지에 붉은 꽃물로 별자리를 그어 만든 점판. 묻기도 전에 답이 떠오를 때가 있다.","lines":["전투 중: 적의 영능력 자원(영력) -25 / 적의 앞으로 5개 행동을 간파 / 부적 사용 횟수 +3 / 나의 나쁜 상태(독·저주·속박 등) 해제 (한 전투에 1번)"]},{"name":"도롱이","sub":"칡 뿌리 ×4 + 고사리 ×3","desc":"칡뿌리와 고사리 줄기를 엮은 비옷. 비는 막아 주는데 입은 사람이 반쯤 덤불처럼 보인다.","lines":["착용 시 인내 +2 · 절제 +1 / 개척: 행동 턴 +2"]},{"name":"여우털 두루마기","sub":"여우 꼬리털 ×4 + 털실 뭉치 ×2","desc":"여우 꼬리털을 털실로 덧댄 두루마기. 입고 있으면 어쩐지 말솜씨가 늘 것 같다.","lines":["착용 시 이해 +2 · 신속 +1"]},{"name":"부적 도포","sub":"봉인 부적 ×1 + 털실 뭉치 ×3","desc":"봉인 부적을 안감에 꿰매 넣은 도포. 걸을 때마다 종이 바스락거리는 소리가 난다.","lines":["착용 시 절제 +2 · 이해 +2"]},{"name":"박쥐 날개 망토","sub":"박쥐 날개 ×4 + 노끈 ×2","desc":"박쥐 날개를 노끈으로 이어 붙인 망토. 펼치면 근사하지만 접을 때 손이 많이 간다.","lines":["착용 시 신속 +3"]},{"name":"담비털 배자","sub":"담비 털 ×3 + 털실 뭉치 ×2","desc":"담비 털로 깃을 두른 배자. 담비에게는 미안하지만 정말 따뜻하다.","lines":["착용 시 인내 +3 · 신속 +2"]},{"name":"매 깃털 철릭","sub":"매 깃털 ×3 + 노끈 ×2","desc":"매 깃털을 어깨에 덧댄 철릭. 입으면 등이 저절로 펴진다.","lines":["착용 시 안목 +3 · 호전 +2 / 개척: 채집·수렵 성공률 +5%"]},{"name":"곰털 덧옷","sub":"곰 털 ×3 + 털실 뭉치 ×3","desc":"반달 무늬 곰 털을 털실로 누빈 덧옷. 한겨울 산꼭대기에서도 땀이 난다.","lines":["착용 시 인내 +5 · 호전 +2"]},{"name":"얼음꽃 한삼","sub":"얼음꽃 ×2 + 털실 뭉치 ×2","desc":"얼음꽃을 털실에 엮어 소매 끝에 단 옷. 소매를 흔들면 서리가 흩날린다.","lines":["착용 시 절제 +4 · 안목 +3"]},{"name":"흰족제비 갖옷","sub":"흰족제비 털 ×3 + 털실 뭉치 ×2","desc":"눈처럼 흰 족제비 털로 지은 갖옷. 눈밭에 서면 정말로 사라진다.","lines":["착용 시 신속 +5 · 안목 +3 / 개척: 채집·수렵 성공률 +8%"]},{"name":"학창의","sub":"학 깃털 ×3 + 털실 뭉치 ×3","desc":"학 깃털을 깃과 소매에 두른 학창의. 입으면 말수가 줄고 오래 살고 싶어진다.","lines":["착용 시 이해 +5 · 절제 +4 · 인내 +3"]},{"name":"토끼풀 화관","sub":"토끼풀 ×5 + 민들레 ×2","desc":"토끼풀과 민들레를 엮은 화관. 쓰고 있으면 누가 와서 네잎을 찾아 준다.","lines":["착용 시 안목 +1 / 개척: 추가 보상 확률 +5%"]},{"name":"산딸기 댕기","sub":"산딸기 ×3 + 오색실 ×1","desc":"산딸기 물을 들인 오색실 댕기. 달콤한 냄새에 벌이 따라온다.","lines":["착용 시 신속 +1 · 이해 +1"]},{"name":"고라니 이빨 목걸이","sub":"고라니 이빨 ×2 + 노끈 ×1","desc":"고라니 이빨을 노끈에 꿴 목걸이. 걸을 때마다 달그락거려 몰래 다니기는 글렀다.","lines":["착용 시 호전 +2"]},{"name":"깃털 노리개","sub":"깃털 다발 ×1 + 오색실 ×2","desc":"깃털 다발을 오색실 술에 단 노리개. 바람이 불면 주인보다 먼저 들뜬다.","lines":["착용 시 신속 +2"]},{"name":"수정 구슬 팔찌","sub":"수정 구슬 ×2 + 노끈 ×1","desc":"수정 구슬을 노끈에 꿴 팔찌. 햇빛 아래에서 손목에 작은 무지개가 생긴다.","lines":["착용 시 안목 +2 · 이해 +1"]},{"name":"곡옥 노리개","sub":"곡옥 ×1 + 오색실 ×2 + 노끈 ×1","desc":"곡옥에 오색실 술을 단 노리개. 옛 무당들이 차던 것과 꼭 닮았다.","lines":["착용 시 이해 +3 · 절제 +1"]},{"name":"벽조목 비녀","sub":"벽조목 패 ×1 + 진주 ×1","desc":"벽조목 패를 깎아 진주를 박은 비녀. 꽂고 있으면 악몽을 덜 꾼다고 한다.","lines":["착용 시 절제 +3 · 인내 +2"]},{"name":"흰까치 깃 머리꽂이","sub":"흰까치 깃 ×2 + 수정 구슬 ×1","desc":"흰까치 깃에 수정 구슬을 단 머리꽂이. 좋은 소식이 오면 깃이 먼저 들썩인다.","lines":["착용 시 안목 +3 · 신속 +2 / 개척: 추가 보상 확률 +10%"]},{"name":"금두꺼비 반지","sub":"금두꺼비 허물 ×1 + 수정 구슬 ×1","desc":"금두꺼비 허물로 수정 구슬을 감싼 반지. 끼고 있으면 길에서 동전을 자주 줍는다.","lines":["착용 시 안목 +3 / 개척: 채집·수렵 성공률 +5% · 추가 보상 확률 +20%"]},{"name":"용마 갈기 갓끈","sub":"용마 갈기 ×1 + 해동청 깃 ×1 + 진주 ×2","desc":"용마 갈기와 해동청 깃에 진주를 꿴 갓끈. 바람 한 점 없는 날에도 혼자 휘날린다.","lines":["착용 시 신속 +4 · 호전 +4 · 안목 +3 / 개척: 행동 턴 +5"]}]},{"id":"kitchen","title":"조리실","kind":"list","intro":"가스불과 커다란 조리대, 각종 식자재가 갖춰진 공간. 이곳에서 식재료를 조합해서 음식을 만들 수 있다.","play":{"to":"kitchen","label":"조리실에서 요리하기"},"items":[{"name":"콩기름","sub":"콩 ×5","desc":"고소함이 가득하다. 콩을 뭐 얼마나 넣어야 하는 건데?","lines":["제작용 재료."]},{"name":"쑥떡","sub":"쑥 ×3 + 쌀 ×2","desc":"전자렌지로 제조. 매점 담당이 전자렌지 닦고 가라고 한소리 했다. 나눠주면 용서해줄지도?","lines":["체력과 의지력 +15"]},{"name":"잉어탕","sub":"잉어 ×3 + 청화물 ×3","desc":"기생충 조심. 손질이 조금 까다롭다. 나이든 입맛이네, 라고 누군가가 말했다.","lines":["전투 중: 일행 전원 체력 +20"]},{"name":"뱀딸기잼","sub":"뱀딸기 ×4 + 설탕 ×3","desc":"대부분의 과일은 설탕을 넣고 가열하면 맛있어진다는 얘기가 있다. 그래서 과학실에 무단침입한 사람 누구냐?","lines":["의지력 +25 / 12시간 동안 절제 +1"]},{"name":"버섯전골","sub":"버섯 ×5","desc":"평범한 버섯전골. 너무 평범하다 못해 밋밋한 맛이 난다.","lines":["전투 중: 일행 전원 체력 +12"]},{"name":"왕버섯전골","sub":"버섯 ×3 + 왕버섯 ×2","desc":"정체를 알 수 없지만 먹을 수 있다는 사실만 명백한 왕버섯 전골.","lines":["전투 중: 일행 전원 체력 +18 · 의지력 +8"]},{"name":"독버섯전골","sub":"독버섯 ×5","desc":"겉보기로는 버섯 전골과 다름이 없어 보인다. 겉보기로는.","lines":["의지력 +35 / 체력 -15 (1 아래로는 내려가지 않는다)"]},{"name":"비빔밥","sub":"취나물 ×2 + 상추 ×2 + 고사리 ×2 + 쌀 ×2","desc":"여럿이 합의하지 않고 가져온 재료로 만든 비빔밥이 제일 맛있다.","lines":["체력 +30 / 의지력 +20"]},{"name":"화전","sub":"진달래 ×1 + 민들레 ×1 + 쌀 ×2","desc":"꽃으로 만들어지는 쫄깃하고 부드러운 전. 달큰하고 화한 맛이 입안 가득 퍼진다.","lines":["체력 +20 / 24시간 동안 이해 +1"]},{"name":"나물무침","sub":"취나물 ×1","desc":"이런저런 나물을 한데 모아 섞어둔 것. 건강에 좋은 맛이 난다.","lines":["체력 +15 / 의지력 +10"]},{"name":"정체불능의 보약","sub":"감초 ×2 + 그믐꽃 ×1 + 초승꽃 ×1 + 청화물 ×1","desc":"산에서 자란 이런저런 것들을 넣어서 만든 보약. 먹어도 되는 거냐는 말은 금지. 이래보여도 손이 꽤 많이 간다.","lines":["체력 +15 / 24시간 동안 무작위 육조 1개 +3"]},{"name":"청화 육수","sub":"청화물 ×3 + 버섯 ×2","desc":"청화물에 버섯을 우려낸 맑은 육수. 이것만 있으면 무엇이든 국이 된다.","lines":["제작용 재료"]},{"name":"도토리 가루","sub":"도토리 ×5","desc":"도토리를 말려 곱게 빻은 가루. 다람쥐가 보면 화낼 양이다.","lines":["제작용 재료"]},{"name":"밤 조청","sub":"밤 ×3 + 볍씨 ×10","desc":"밤과 볍씨를 오래 고아 낸 끈적한 조청. 숟가락이 꽂힌 채로 서 있다.","lines":["제작용 재료"]},{"name":"약재 달임물","sub":"당귀 ×2 + 감초 ×2 + 도라지 ×1","desc":"당귀 · 감초 · 도라지를 함께 달인 물. 냄새만 맡아도 몸이 좋아지는 기분이다. 맛은 묻지 말자.","lines":["제작용 재료"]},{"name":"머루즙","sub":"머루 ×4","desc":"머루를 짓이겨 거른 진한 보랏빛 즙. 포도즙과 헷갈리면 머루가 서운해한다.","lines":["제작용 재료"]},{"name":"보릿가루","sub":"보리 씨앗 ×10","desc":"보리 씨앗을 볶아 빻은 가루. 보리차가 되는 꿈은 이렇게 끝났다.","lines":["제작용 재료"]},{"name":"나물 데침","sub":"취나물 ×2 + 고사리 ×2","desc":"취나물과 고사리를 함께 데쳐 물기를 짠 것. 이대로 먹어도 되지만 참는 게 좋다.","lines":["제작용 재료"]},{"name":"밀가루","sub":"밀 씨앗 ×10","desc":"밀 씨앗을 빻아 체에 친 가루. 열 알로 이만큼 나온 게 신기하다.","lines":["제작용 재료"]},{"name":"산딸기 절임","sub":"산딸기 ×6","desc":"산딸기를 소금물에 절인 것. 새콤하다 못해 눈이 감긴다.","lines":["체력 회복: 일행에게 건네면 +14, 자신이 먹으면 +6"]},{"name":"보리개떡","sub":"보릿가루 ×1 + 산딸기 ×2","desc":"보릿가루에 산딸기를 박아 찐 투박한 떡. 생긴 건 그래도 맛은 정직하다.","lines":["체력 +12"]},{"name":"버섯 구이","sub":"버섯 ×3","desc":"버섯을 꼬치에 꿰어 구운 것. 먹어도 되는 버섯만 골랐는지 한 번 더 확인하자.","lines":["개척 중: 개척 행동 턴 +2"]},{"name":"당근 버섯 볶음","sub":"당근 ×2 + 버섯 ×2 + 콩기름 ×1","desc":"당근과 버섯을 콩기름에 볶은 반찬. 흐물파와 딱딱파가 이 접시 앞에서는 휴전한다.","lines":["개척 중: 다음 3번의 채집·수렵 성공률 +10%"]},{"name":"뱀딸기 화채","sub":"뱀딸기 ×3 + 산딸기 ×2","desc":"뱀딸기와 산딸기를 띄운 화채. 뱀딸기만 남기는 사람이 꼭 있다.","lines":["의지력 회복: 일행에게 건네면 +15, 자신이 먹으면 +6"]},{"name":"민들레 차","sub":"민들레 ×3 + 청화물 ×1","desc":"민들레를 말려 청화물에 우린 차. 쌉싸름해서 졸음이 달아난다.","lines":["개척 중: 개척 행동 턴 +3"]},{"name":"청화 버섯국","sub":"청화 육수 ×1 + 버섯 ×2","desc":"청화 육수에 버섯을 듬뿍 넣은 국. 맑은 국물에 버섯이 동동 떠 있다.","lines":["체력 +18 / 의지력 +8"]},{"name":"배춧국","sub":"배추 ×2 + 청화 육수 ×1","desc":"청화 육수에 배추를 넣고 끓인 국. 배추가 포기한 덕에 우리는 국을 먹는다.","lines":["체력 +25"]},{"name":"토끼풀 샐러드","sub":"토끼풀 ×3 + 상추 ×2 + 방울토마토 ×2","desc":"토끼풀과 상추, 방울토마토를 버무린 샐러드. 토끼가 보면 줄을 선다.","lines":["개척 중: 이번 개척 동안 추가 보상 확률 +15%"]},{"name":"쑥버무리","sub":"쑥 ×3 + 보릿가루 ×1","desc":"쑥과 보릿가루를 버무려 찐 떡. 향이 진해서 한 입이면 봄이 온다.","lines":["개척 중: 5턴 동안 요괴가 다가오지 못하고, 마주쳐도 비켜 간다"]},{"name":"쑥 감자전","sub":"감자 ×3 + 쑥 ×1 + 콩기름 ×1","desc":"감자를 갈아 쑥을 넣고 콩기름에 부친 전. 가장자리가 바삭할 때 먹어야 한다.","lines":["개척 중: 3턴 동안 요괴가 다가오지 못하고, 마주쳐도 비켜 간다 / 체력 +10"]},{"name":"고사리 볶음","sub":"고사리 ×3 + 콩기름 ×1","desc":"고사리를 콩기름에 달달 볶은 나물. 충분히 삶았는지가 맛을 가른다.","lines":["개척 중: 다음 4번의 채집·수렵 성공률 +12%"]},{"name":"나물 수제비","sub":"밀가루 ×1 + 나물 데침 ×1 + 청화 육수 ×1","desc":"밀가루 반죽을 뜯어 청화 육수에 나물 데침과 끓인 수제비. 손이 많이 간 만큼 든든하다.","lines":["개척 중: 개척 행동 턴 +4"]},{"name":"잉어 구이","sub":"잉어 ×2 + 쑥 ×1","desc":"잉어에 쑥을 채워 구운 것. 비린내는 쑥이 다 가져갔다.","lines":["체력 +15 / 24시간 동안 인내 +1"]},{"name":"수세미 나물","sub":"수세미 열매 ×2 + 콩기름 ×1","desc":"어린 수세미 열매를 콩기름에 볶은 나물. 설거지 생각은 잠시 접어 두자.","lines":["개척 중: 지금 칸(옆 칸 장애물 포함) 대상의 남은 시도 +1"]},{"name":"도토리묵","sub":"도토리 가루 ×1 + 청화물 ×2","desc":"도토리 가루를 청화물에 쑤어 굳힌 묵. 젓가락으로 집으면 도망간다.","lines":["개척 중: 3턴 동안 동물·영물이 제자리에 멈춘다"]},{"name":"왕버섯 구이","sub":"왕버섯 ×1 + 콩기름 ×1","desc":"왕버섯을 두툼하게 썰어 콩기름에 구운 것. 한 조각이 손바닥만 하다.","lines":["체력 +30"]},{"name":"당귀 차","sub":"당귀 ×2 + 청화물 ×1","desc":"당귀를 청화물에 우린 차. 약 냄새가 진동하지만 몸은 확실히 따뜻해진다.","lines":["체력 회복: 일행에게 건네면 +25, 자신이 먹으면 +10 / 의지력 회복: 일행에게 건네면 +15, 자신이 먹으면 +6"]},{"name":"밤죽","sub":"밤 ×4 + 볍씨 ×10","desc":"밤을 으깨 볍씨와 함께 쑨 죽. 달큰하고 부드러워서 아플 때 생각난다.","lines":["체력 +45"]},{"name":"도라지 정과","sub":"도라지 ×3 + 밤 조청 ×1","desc":"도라지를 밤 조청에 졸인 정과. 목이 칼칼할 때 하나씩 꺼내 먹는다.","lines":["전투 중: 나의 나쁜 상태(독·저주·속박 등) 해제 / 의지력 +8"]},{"name":"감초 엿","sub":"감초 ×2 + 밤 조청 ×1","desc":"감초를 밤 조청에 넣어 굳힌 엿. 약방의 감초가 드디어 주인공이 되었다.","lines":["의지력 +25"]},{"name":"머루 화채","sub":"머루즙 ×1 + 청화물 ×1 + 산딸기 ×2","desc":"머루즙에 청화물과 산딸기를 띄운 화채. 보랏빛이 예뻐서 마시기 아깝다.","lines":["의지력 +45"]},{"name":"진주 경단","sub":"진주 ×1 + 밤 조청 ×1 + 볍씨 ×10","desc":"진주 가루를 넣어 빚은 경단을 밤 조청에 굴린 것. 씹을 때마다 은은하게 반짝인다.","lines":["체력 회복: 일행에게 건네면 +20, 자신이 먹으면 +8 / 받는 사람의 나쁜 상태(독·저주·속박 등) 해제"]},{"name":"칡차","sub":"칡 뿌리 ×2 + 청화물 ×1","desc":"칡뿌리를 우린 차. 판 사람의 고생이 국물에 그대로 녹아 있다.","lines":["개척 중: 이번 개척 동안 인내 +5 · 절제 +3"]},{"name":"십전대보탕","sub":"약재 달임물 ×1 + 산삼 ×1 + 감초 ×1","desc":"약재 달임물에 산삼과 감초를 더 넣고 달인 탕. 한 모금에 열 가지 기운이 돈다고 한다.","lines":["24시간 동안 모든 육조 +1"]},{"name":"더덕 구이","sub":"더덕 ×3 + 콩기름 ×1","desc":"더덕을 두드려 펴서 콩기름에 구운 것. 산 냄새가 부엌 가득 퍼진다.","lines":["개척 중: 이번 개척 동안 안목 +4 · 이해 +4"]},{"name":"느타리 전골","sub":"느타리버섯 ×3 + 청화 육수 ×1","desc":"느타리버섯을 청화 육수에 끓인 전골. 버섯끼리 모여 사는 모습이 정겹다.","lines":["체력 +35 / 의지력 +15"]},{"name":"네잎클로버 화전","sub":"네잎클로버 ×1 + 진달래 ×1 + 밀가루 ×1","desc":"밀가루 반죽에 네잎클로버와 진달래를 올려 부친 화전. 먹으면 운이 좋아질 것 같지만 이미 하나 썼다.","lines":["개척 중: 다음 1번의 성공 보상이 2배"]},{"name":"꽃물 떡","sub":"초승꽃 ×1 + 그믐꽃 ×1 + 볍씨 ×10","desc":"초승꽃과 그믐꽃 물로 물들인 붉은 떡. 너무 붉어서 처음 보는 사람은 놀란다.","lines":["전투 중: 일행 전원 체력 +10 / 일행 전원의 나쁜 상태(독·저주·속박 등) 해제"]},{"name":"오미자 화채","sub":"오미자 ×3 + 청화물 ×1 + 진달래 ×1","desc":"오미자를 우린 붉은 물에 진달래를 띄운 화채. 다섯 가지 맛이 차례로 지나간다.","lines":["개척 중: 개척 행동 턴 +2 / 다음 5번의 채집·수렵 성공률 +20%"]},{"name":"송이 솥밥","sub":"송이버섯 ×2 + 볍씨 ×10","desc":"송이버섯을 얹어 지은 솥밥. 뚜껑을 여는 순간 솔숲이 통째로 들어온다.","lines":["전투 중: 일행 전원 체력 +35 · 의지력 +15"]},{"name":"용궁탕","sub":"이무기 비늘 ×1 + 잉어 ×2 + 청화 육수 ×1","desc":"이무기 비늘과 잉어를 청화 육수에 끓인 탕. 먹고 나면 물속에서도 숨을 오래 참을 수 있을 것 같다.","lines":["체력 +30 / 24시간 동안 신속 +2 · 인내 +2"]},{"name":"녹용 보약","sub":"녹용 ×1 + 약재 달임물 ×1","desc":"녹용을 약재 달임물에 넣어 오래 달인 보약. 한 사발이면 사흘은 뛰어다닌다.","lines":["전투 중: 전투 중 호전 +4 · 인내 +2 (다인 전투는 그 전투 동안, 단독 전투는 20분) / 체력 +20"]},{"name":"잣죽","sub":"잣 ×3 + 볍씨 ×10","desc":"잣을 곱게 갈아 볍씨와 쑨 죽. 고소한 맛이 숟가락마다 묻어난다.","lines":["개척 중: 개척 행동 턴 +8 / 의지력 +20"]},{"name":"잣 강정","sub":"잣 ×3 + 밤 조청 ×1","desc":"잣을 밤 조청으로 뭉쳐 굳힌 강정. 이 사이에 끼는 건 각오해야 한다.","lines":["체력 회복: 일행에게 건네면 +30, 자신이 먹으면 +12 / 받는 사람의 다음 행동 피해 2배(1턴)"]},{"name":"금두꺼비 환","sub":"금두꺼비 허물 ×1 + 감초 ×2","desc":"금두꺼비 허물에 감초를 섞어 빚은 환. 삼키고 나면 지갑을 한 번 확인하게 된다.","lines":["개척 중: 다음 2번의 성공 보상이 2배 / 이번 개척 동안 추가 보상 확률 +25%"]},{"name":"천종삼 정과","sub":"천종삼 ×1 + 밤 조청 ×1","desc":"천종삼을 밤 조청에 오래 졸인 정과. 아까워서 한 번에 다 먹은 사람이 없다.","lines":["전투 중: 전투불능 시 1회 체력 1로 부활 대기(한 전투에 부활 아이템은 1번) / 체력 +50 / 의지력 +30"]},{"name":"얼음꽃 빙수","sub":"얼음꽃 ×2 + 머루즙 ×1","desc":"얼음꽃을 갈아 머루즙을 끼얹은 빙수. 한겨울에 먹어도 머리가 띵하다.","lines":["전투 중: 일행 전원 체력 +20 · 의지력 +30 / 일행 전원 그 전투 동안 신속 +3"]},{"name":"솜다리 꽃차","sub":"솜다리 ×2 + 청화물 ×1","desc":"솜다리를 청화물에 띄운 꽃차. 높은 곳의 공기 맛이 난다.","lines":["개척 중: 개척 행동 턴 +5 / 이번 개척 동안 모든 육조 +6"]},{"name":"오복 환","sub":"오복 날개막 ×1 + 약재 달임물 ×1","desc":"오복 날개막을 약재 달임물에 개어 빚은 환. 다섯 가지 복 중 무엇이 올지는 먹어 봐야 안다.","lines":["24시간 동안 무작위 육조 2개 +4 / 영력 +20"]},{"name":"불로장생탕","sub":"불로초 ×1 + 천종삼 ×1 + 약재 달임물 ×1","desc":"불로초와 천종삼을 약재 달임물에 함께 달인 탕. 이걸 끓인 솥은 다시는 평범한 솥이 될 수 없다.","lines":["체력 완전 회복 / 의지력 완전 회복 / [쇠약] 즉시 회복 / 영력 +40"]},{"name":"귀갑 보약","sub":"천년거북 등딱지 ×1 + 약재 달임물 ×1","desc":"천년거북 등딱지를 약재 달임물에 넣어 고아 낸 보약. 한 숟갈마다 별자리 하나만큼의 세월이 담겼다.","lines":["48시간 동안 모든 육조 +3 / 영력 +60"]}]},{"id":"board","title":"패 놀이터","kind":"list","intro":"함께하는 판놀이는 서버 연결이 필요해 아직 열리지 않았다.","items":[{"name":"요트 다이스","sub":"판놀이","desc":"주사위 다섯 개로 족보를 채운다.","lines":[]},{"name":"윷놀이","sub":"판놀이","desc":"윷을 던져 말을 먼저 내보낸다.","lines":[]},{"name":"루미큐브","sub":"판놀이","desc":"패를 묶어 먼저 손을 비운다.","lines":[]},{"name":"오목","sub":"판놀이","desc":"다섯 알을 먼저 잇는다.","lines":[]},{"name":"홀짝","sub":"판놀이","desc":"화투패의 홀짝을 맞힌다.","lines":[]}]}]}]},"west":{"title":"생활관","tabs":[{"id":"dorm","name":"기숙사","hanja":"黑","sections":[{"id":"intro","title":"둘러보기","kind":"text","paras":["사당을 중심으로 북쪽에 놓인 건물. 당신이 살아가는 검은 공간. 바닥과 벽은 그나마 알아볼 수 있게끔 희고 노란 줄들이 그어져 있으나 가끔 밤에 움직이면 거리감이 분간이 가질 않아 해가 진 뒤에 이동할 때엔 최소 3명에서 많으면 다섯명씩 움직이라고 주의를 받는다. 4시간 마다 선생님들이 복도를 돌아다니면서 길 잃은 아이들을 다시 방으로 돌려보내곤 한다.","이런 수상쩍은 구석만 뺀다면 시설은 양호하다. 넉넉한 방 크기에 푹신한 매트리스, 솜이 좀 빠진 것 같은 베개와 깨끗한 창틀. 가끔가다 전 주인이 쓰다가 남긴 가구나 물건이 남아있기도 한데, 그곳에 문장이나 저주가 걸려있진 않나 확인하는 것을 잊지 말도록 하자."]},{"id":"train","title":"수련","kind":"text","paras":["수련: 5~300분(5분 단위). 끝까지 수련하면 영력이 오른다."],"play":{"to":"train","label":"수련 시작하기"}},{"id":"sleep","title":"잠","kind":"text","paras":["침대에 누워 6시간을 푹 잔다. 일어나면 체력과 의지력이 가득 차고 영력이 오른다."],"play":{"to":"sleep","label":"잠자리에 들기"}},{"id":"stats","title":"스탯 올리기","kind":"text","paras":["모은 영력으로 육조 스탯을 1씩 올린다. (비용 = 지금 수치 × 10)"],"play":{"to":"stats","label":"스탯 올리기"}},{"id":"store","title":"매점","kind":"list","intro":"기숙사 1층 구석에 위치한 매점. 오전 8시부터 밤 10시까지 운영하고 있다.\n\n간식거리부터 수업 준비물, 실습 재료 등을 다양하게 판매하고 있다. 정해지지 않은 시간 외에도 전자레인지를 사용하겠다고 침입하는 사람이 존재는 하지만 교칙상으로는 금지되어 있으니 주의할 것. 쓸만한 재료의 경우 판매도 가능하다.\n\n문 앞에는 개교를 기념하여 심었다는 벚꽃나무가 자라고 있다. 학교와 나이가 같거나 많을 나무는 봄이 되면 짙은 분홍빛으로 빛나고, 사람 서넛 정도는 가뿐히 삼킬 것만 같다. 사람을 먹는다는 교내 괴담이 있으나, 사실 불명. 이 나무 탓에 매점 아르바이트는 '산'과 관련된 신을 모시는 학생이 맡아온다는 불문율이 있다.","play":{"to":"store","label":"매점 들어가기"},"items":[{"play":{"to":"store","label":"매점에서 사기"},"name":"사과맛 피크닉","sub":"5냥","desc":"평범한 사과맛 피크닉, 독은 들어있지 않다. 전투중에 마셔도 목에 걸리지 않는다.","lines":["의지력 +15, 전투 중 사용 가능","완성품 · 전투 중 사용 가능 · #턴소모無 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"가나다 초콜릿","sub":"8냥","desc":"탈지분유 맛이 난다. 크래커 과자에 껴먹는게 요즘의 소소한 유행이다.","lines":["의지력 +30","완성품"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"컵라면","sub":"8냥","desc":"급식이 맛없을 때면 금방 재고가 떨어진다. 미리미리 사두는 사람들도 있으니 참고할 것.","lines":["체력 +20","완성품"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"만두","sub":"12냥","desc":"고기만두로 통일됐다. 김치만두를 원한다면 매점 주인에게 문의해보자.","lines":["체력 +30","완성품"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"마이쮸","sub":"5냥","desc":"친해지고 싶은 상대에게 나눠주자. 전투 중에는 같이 싸우는 파티원에게도(물론 혼자 먹어도) 건넬 수 있다.","lines":["전투 중: 파티원(나 자신 포함) 한 명에게 건네면 그 사람의 다음 행동 피해가 1턴 동안 2배가 된다. \n전투가 아닐 때: NPC에게 주면 호감도가 오른다.","완성품 · 전투 중 사용 가능 · #턴소모無 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"에너지드링크","sub":"20냥","desc":"날개를 달아줘요. 어쩐지 죽어도 죽지 않을 것 같다.","lines":["1회에 한하여 전투불능 패널티 없이, 또한 전투를 종료하지 않고 HP1로 부활시킨다. 의지력은 회복되지 않는다. 전투불능이 되기 전 미리 먹어둬야 효과가 바로 발휘되며, 전투불능 이후에는 사용할 수 없다. 한 전투에 1회만 쓸 수 있다 (부활에 쓰고 나서도 같은 전투에서는 다시 마실 수 없다).","완성품 · 전투 중 사용 가능 · #턴소모無 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"콘 아이스크림","sub":"15냥","desc":"콘 아이스크림, 와플이 바삭바삭하고 조금 비싸다. 끄트머리에 초콜릿이 들어있다.","lines":["체력 +10, 의지력 +5","완성품"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"봉지 과자","sub":"12냥","desc":"까서 먹고 있으면 주변 사람들이 몰려와서 한 입씩 뺏어먹는다.","lines":["전투 중: 파티 전원의 체력이 15 회복된다. (일행 전투에서만 쓸 수 있다)","완성품 · 전투 중 사용 가능 · #턴소모有 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"조각 케이크","sub":"15냥","desc":"깜짝 파티를 하기에 나쁘지 않다. 설령 전투중이라 하더라도 기념일은 잊지 말도록 해.","lines":["전투 중: 파티 전원의 의지력이 15 회복된다. (일행 전투에서만 쓸 수 있다)","완성품 · 전투 중 사용 가능 · #턴소모有 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"폭죽","sub":"30냥","desc":"깜짝 파티를 하기에 나쁘지 않다. 하지만 미리 예고하지 않으면 친구들이 너를 노려볼지도 모른다.","lines":["사용 시 자신을 제외한 일행 전원의 다음 1회 공격력이 2배가 된다. 단, 사용한 자신은 그 즉시부터 1턴 동안 행동불능이 되며, 자신에게는 2배 효과가 적용되지 않는다. (일행 전투에서만 쓸 수 있다)","완성품 · 전투 중 사용 가능 · #턴소모有 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"쌍쌍바","sub":"10냥","desc":"더 큰 쪽을 누가 가져가느냐에 따라 우정이 갈라진다는 이야기가 있다. 나는 이 이야기를 참 좋아한다.","lines":["체력 회복. 파티원에게 건네면 +20, 자기 자신이 사용하면 +5.","완성품 · 전투 중 사용 가능 · #턴소모有 · 일행"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"핫바","sub":"10냥","desc":"이거 돌린다고 밤중에 매점 문 따고 들어와 전자렌지를 돌리는 너구리들이 존재한다는 풍문이 있다.","lines":["현재 지속 중인 [쇠약]의 남은 유효시간을 1시간으로 대폭 줄인다.","완성품"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"붓","sub":"12냥","desc":"털끝이 가지런한 평범한 붓. 부적이든 서예든, 일단 이게 있어야 시작이다.","lines":["제작용 재료.","재료"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"한지","sub":"6냥","desc":"매끈하고 질긴 새 한지. 번지지 않아서 글씨 쓰기 좋다.","lines":["제작용 재료.","재료"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"조각칼","sub":"10냥","desc":"결계 생성에 주로 사용한다. 손을 찍어버리지 않도록 조심하도록.","lines":["제작용 재료.","재료"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"주머니","sub":"8냥","desc":"손가락 두 마디 크기의 주머니, 작은 거라면 넣을 수 있다.","lines":["제작용 재료.","재료"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"먹","sub":"10냥","desc":"곱게 갈면 짙은 먹물이 나오는 새 먹. 부러지지 않았다.","lines":["제작용 재료.","재료"]},{"play":{"to":"store","label":"매점에서 사기"},"name":"가방","sub":"50냥","desc":"어깨에 메는 천 가방. 교과서보다 다른 것이 더 많이 들어 있는 게 학생 가방의 숙명이다.","lines":["[가방 열기]로 물건을 넣고 꺼낸다. 가방 하나에 40칸(소지품과 같은 칸 규칙: 재료 99개 · 그 밖 9개씩). 누구나 하나씩 갖고 시작한다.","완성품 · 가방"]}]},{"id":"cafeteria","title":"급식실","kind":"list","intro":"1학년부터 3학년까지 모두가 한 자리에 모여 든든한 밥을 먹는다.","items":[{"name":"아침","sub":"07:00 ~ 08:30","desc":"","lines":[]},{"name":"점심","sub":"12:30 ~ 13:30","desc":"","lines":[]},{"name":"저녁","sub":"18:00 ~ 19:30","desc":"","lines":[]}]}]}]},"south":{"title":"비령산 금역","tabs":[{"id":"gym","name":"뒷산","hanja":"赤","sections":[{"id":"intro","title":"둘러보기","kind":"text","paras":["사당을 중심으로 남쪽에 놓인 산. 산의 둘레를 따라 붉은 띠가 걸쳐져 있으며, 가끔가다 띠가 걸린 고리가 헐거워져있거든 모두가 그 날 수업을 그만두고 이의 보수에 집중한다. 실습터로 향하는 길은 안전히 닦여 있지만, 그 외의 길에는 무엇이 숨겨져 있을지 아무도 모른다.","어떤 시간이 됐다 하더라도 사람들이 머물고 있다. 때로 열기를 참지 못한 학생들이 점심 시간 잘 시간을 아껴 가며 저들끼리 판을 벌이곤 한다. 산 초입의 천하대장군과 지하여장군은 특유의 표정으로 아이들을 그저 물끄러미 바라보고 있다."]},{"id":"practice","title":"퇴마 실습","kind":"list","intro":"영력을 얻는 승리는 하루 3회. 전투 튜토리얼도 여기서 연다.","play":{"to":"battle","label":"퇴마 실습 열기"},"items":[{"play":{"to":"battle/scarecrow","label":"이 상대와 싸우기"},"name":"허수아비 잡귀","sub":"二단계 · 단독","desc":"밭에서 떠도는 잡귀. 움직임이 단순하다.","lines":["체력 64 · 공격력 6 · 행동력 6 · 영력 5","영능력 [혼 빨기] 의지력을 빨아들인다."]},{"play":{"to":"battle/snake","label":"이 상대와 싸우기"},"name":"먹구렁이","sub":"三단계 · 단독","desc":"묵은 담벼락 밑에서 몸을 부풀려 덮치는 구렁이.","lines":["체력 99 · 공격력 11 · 행동력 9 · 영력 8","영능력 [휘감기] 몸을 감아 조이고, 다음 내 턴엔 막기를 할 수 없다."]},{"play":{"to":"battle/wonhon","label":"이 상대와 싸우기"},"name":"묵은 원귀","sub":"四단계 · 단독","desc":"오래 묵어 독이 오른 원귀. 한 방이 무겁다.","lines":["체력 147 · 공격력 16 · 행동력 14 · 영력 13","영능력 [원한의 저주] 세 번의 상대 턴 동안 매번 피해가 스며든다."]},{"play":{"to":"battle/foxfire","label":"이 상대와 싸우기"},"name":"여우불","sub":"二단계 · 2인","desc":"밤길에 여우 울음 같은 소리를 내며 떠도는 푸른 불꽃 무리. 혼자서는 벅차지만 둘이 함께라면 해볼 만하다.","lines":["체력 163 · 공격력 7 · 행동력 7 · 영력 6","영능력 [불똥 흩뿌리기] 사방으로 튀는 불똥. 막을 수 없는 피해를 입는다."]},{"play":{"to":"battle/dueoksini","label":"이 상대와 싸우기"},"name":"두억시니","sub":"三단계 · 2인","desc":"어둠 속에서 사람을 짓누르는 사나운 야차. 둘은 모여야 맞설 수 있다.","lines":["체력 294 · 공격력 13 · 행동력 10 · 영력 10","영능력 [짓누르는 그림자] 막을 수 없는 일격으로 몸을 짓누르고, 의지력을 빨아들이며, 다음 내 턴엔 막기를 할 수 없다."]},{"play":{"to":"battle/bulgasari","label":"이 상대와 싸우기"},"name":"불가살이","sub":"四단계 · 3인","desc":"쇠붙이를 먹고 자란다는 불길한 괴수. 쇠도 불도 가리지 않고 삼키며, 몸이 상할수록 사나워진다. 셋은 모여야 겨우 맞설 수 있다.","lines":["체력 1155 · 공격력 21 · 행동력 14 · 영력 16","영능력 [쇠 갉아먹기] 한 사람의 살과 의지를 갉아먹는다. 막을 수 없는 피해를 주고 의지력을 빨아들인다.","영능력 [불길 내뿜기] 일행 전원에게 불길을 뿜는다. 막을 수 없는 피해를 입고, 다음 내 턴엔 막기를 할 수 없다."]},{"play":{"to":"battle/geuseundae","label":"이 상대와 싸우기"},"name":"그슨대","sub":"六단계 · 3인","desc":"어둠 속에서 사람 앞을 가로막는 그림자 거인. 올려다볼수록 끝없이 커진다고 한다. 셋은 모여야 맞설 수 있다.","lines":["체력 2226 · 공격력 30 · 행동력 18 · 영력 24","영능력 [내리누르기] 한 사람을 거대한 손바닥으로 내리누른다. 막을 수 없는 피해를 주고, 다음 3라운드 동안 영능력을 봉인한다.","영능력 [어둠 드리우기] 일행 전원 위로 그림자를 드리운다. 막을 수 있는 피해를 주는 대신 의지력을 더 많이 빨아들인다."]}]},{"id":"bestiary","title":"전투 데이터","kind":"list","intro":"둘레길 [추가전투]의 적 50종. 一~十단계, 단계마다 단독 3 · 파티 1 · 보스 1.","play":{"to":"extra/1","label":"추가전투 열기"},"items":[{"play":{"to":"battle/mongdangbi","label":"이 상대와 싸우기"},"name":"몽당비 도깨비","sub":"二단계 · 단독 · 권장 스탯 3~4","desc":"닳고 닳은 몽당빗자루가 밤마다 일어나 마당을 쓸고 다닌다. 쓸어 담는 것이 먼지만은 아니다.","lines":["체력 69 · 공격력 7 · 행동력 7 · 영력 5","영능력 [쓸어내기] 닳은 빗자루로 앞날을 싹 쓸어 버린다. 간파해 둔 행동이 지워지고 새로 굴러간다."]},{"play":{"to":"battle/yagwanggwi","label":"이 상대와 싸우기"},"name":"야광귀","sub":"二단계 · 단독 · 권장 스탯 3~4","desc":"설날 밤 집집이 내려와 발에 맞는 신을 신고 가 버리는 귀신. 신을 잃은 사람은 한 해 운수가 나쁘다고 한다.","lines":["체력 69 · 공격력 8 · 행동력 9 · 영력 5","영능력 [신 훔치기] 신과 함께 주머니를 채 간다. 한동안 아이템을 꺼낼 수 없다."]},{"play":{"to":"battle/dalgyal-gwisin","label":"이 상대와 싸우기"},"name":"달걀귀신","sub":"二단계 · 단독 · 권장 스탯 3~4","desc":"눈도 코도 입도 없이 매끈한 얼굴만 달린 귀신. 돌아보는 순간 그 얼굴이 코앞에 있다.","lines":["체력 71 · 공격력 7 · 행동력 7 · 영력 7","영능력 [맨얼굴] 아무것도 없는 얼굴을 들이민다. 온몸이 굳어 한 턴 동안 움직일 수 없다."]},{"play":{"to":"battle/dungap-jwi","label":"이 상대와 싸우기"},"name":"둔갑쥐 떼","sub":"二단계 · 파티 · 권장 스탯 3~4","desc":"사람이 깎아 버린 손톱을 주워 먹고 사람 흉내를 내게 된 쥐들. 한 마리를 쫓으면 열 마리가 튀어나온다.","lines":["체력 193 · 공격력 17 · 행동력 7 · 영력 5","영능력 [쥐 떼 부르기] 찍찍 소리와 함께 쥐 떼가 몰려든다. 한동안 라운드가 끝날 때마다 누군가를 문다."]},{"play":{"to":"battle/kim-seobang","label":"이 상대와 싸우기"},"name":"김서방 도깨비","sub":"二단계 · 보스 · 권장 스탯 3~4","desc":"메밀묵이라면 사족을 못 쓰는 덩치 큰 도깨비. 마주친 사람마다 씨름 한 판을 청하는데, 지는 법을 모른다.","lines":["체력 442 · 공격력 11 · 행동력 7 · 영력 5","영능력 [메치기] 한 사람을 번쩍 들어 메친다. 지금 체력의 3분의 1을 앗아 가며 막기도 인내도 소용없다.","영능력 [도깨비방망이] 방망이를 크게 휘둘러 일행 전원을 후려친다. 한 방의 힘을 여럿이 나눠 맞으니, 사람이 많을수록 덜 아프다."]},{"play":{"to":"battle/mangtae-halabeom","label":"이 상대와 싸우기"},"name":"망태 할아범","sub":"三단계 · 단독 · 권장 스탯 6~8","desc":"해 질 녘까지 밖을 쏘다니는 아이를 망태기에 담아 간다는 노인. 망태기 속은 끝도 없이 깊다.","lines":["체력 107 · 공격력 8 · 행동력 9 · 영력 9","영능력 [해 질 녘] 해가 지면 망태 할아범이 온다. 싸움이 길어질수록 더 아프게 후려친다."]},{"play":{"to":"battle/mongdal-gwisin","label":"이 상대와 싸우기"},"name":"몽달귀신","sub":"三단계 · 단독 · 권장 스탯 6~8","desc":"장가를 못 가고 죽은 총각의 넋. 짝 없는 서러움이 오래 묵어 지나가는 사람에게 들러붙는다.","lines":["체력 119 · 공격력 12 · 행동력 10 · 영력 9","영능력 [들러붙기] 서러운 한이 들러붙는다. 한동안 공격·부적을 쓸 때마다 체력이 빠진다."]},{"play":{"to":"battle/dokgak-gwi","label":"이 상대와 싸우기"},"name":"독각귀","sub":"三단계 · 단독 · 권장 스탯 6~8","desc":"다리가 하나뿐인 외다리 도깨비. 껑충 뛰어올라 온몸으로 내리찍는다.","lines":["체력 110 · 공격력 15 · 행동력 11 · 영력 9","영능력 [외발 뛰기] 외발로 껑충 뛰어 곧바로 한 번 더 움직인다."]},{"play":{"to":"battle/gaekgwi","label":"이 상대와 싸우기"},"name":"객귀 떼","sub":"三단계 · 파티 · 권장 스탯 6~8","desc":"길에서 객사해 제삿밥 한 번 얻어먹지 못한 떠돌이 귀신들. 사람 냄새만 맡으면 우르르 몰려든다.","lines":["체력 333 · 공격력 19 · 행동력 10 · 영력 12","영능력 [넋 뒤바꾸기] 떠도는 넋들이 일행의 몸을 뒤바꾼다. 가장 멀쩡한 사람과 가장 다친 사람의 체력 비율이 맞바뀐다."]},{"play":{"to":"battle/jangsanbeom","label":"이 상대와 싸우기"},"name":"장산범","sub":"三단계 · 보스 · 권장 스탯 6~8","desc":"눈처럼 흰 털을 휘날리는 범. 사람 목소리를 흉내 내 아는 이의 목소리로 부르고, 돌아본 사람을 데려간다.","lines":["체력 500 · 공격력 34 · 행동력 10 · 영력 9","영능력 [목소리 흉내] 익숙한 목소리로 한 사람을 부른다. 다음 턴에 고른 행동이 멋대로 바뀐다.","영능력 [흰 털 냄새] 흰 털을 한 사람에게 묻혀 둔다. 한동안 한 사람을 노리는 공격은 모두 그 사람에게 간다."]},{"play":{"to":"battle/heokkaebi","label":"이 상대와 싸우기"},"name":"허깨비","sub":"四단계 · 단독 · 권장 스탯 10","desc":"있는 듯 없는 듯 눈앞에 어른거리는 헛것. 베어도 흩어졌다가 다시 모여든다.","lines":["체력 146 · 공격력 14 · 행동력 13 · 영력 16","영능력 [헛것 보이기] 안개 속에 헛것을 띄운다. 앞으로 보이는 행동 몇 개는 거짓이다."]},{"play":{"to":"battle/daemang","label":"이 상대와 싸우기"},"name":"대망이","sub":"四단계 · 단독 · 권장 스탯 10","desc":"천 년을 묵고도 용이 되지 못한 큰 구렁이. 그 한을 사람을 삼켜 달랜다.","lines":["체력 149 · 공격력 12 · 행동력 12 · 영력 13","영능력 [통째로 삼키기] 통째로 삼키려 든다. 막을 수 없고, 입힌 피해만큼 체력을 되찾는다."]},{"play":{"to":"battle/songaksi","label":"이 상대와 싸우기"},"name":"손각시","sub":"四단계 · 단독 · 권장 스탯 10","desc":"시집 한 번 못 가 보고 죽은 처녀의 넋. 밤마다 서럽게 울어 듣는 사람의 기운을 앗아 간다.","lines":["체력 168 · 공격력 15 · 행동력 13 · 영력 16","영능력 [서러운 울음] 구슬픈 울음에 싸울 기운이 빠진다. 한동안 호전이 절반이 된다."]},{"play":{"to":"battle/imae-mangryang","label":"이 상대와 싸우기"},"name":"이매망량","sub":"四단계 · 파티 · 권장 스탯 10","desc":"산의 정령 이매와 물의 정령 망량. 늘 짝을 지어 다니며 길 잃은 사람을 산과 물 사이에 가둔다.","lines":["체력 508 · 공격력 25 · 행동력 13 · 영력 13","영능력 [산과 물 잇기] 산의 정과 물의 정이 두 사람을 잇는다. 한쪽이 다치면 다른 쪽도 절반만큼 다친다."]},{"play":{"to":"battle/cheonnyeon-jine","label":"이 상대와 싸우기"},"name":"천년지네","sub":"四단계 · 보스 · 권장 스탯 10","desc":"마을 처녀를 제물로 받아 온 천 년 묵은 지네. 독 기운이 서린 몸은 허물을 벗을 때마다 새로 돋는다.","lines":["체력 803 · 공격력 17 · 행동력 13 · 영력 13","영능력 [독니] 한 사람을 독니로 문다. 독은 겹겹이 쌓이고 싸움이 끝날 때까지 빠지지 않는다.","영능력 [독안개] 독안개를 깔아 일행을 덮는다. 한동안 웅크리면 오히려 독을 들이마신다."]},{"play":{"to":"battle/changgwi","label":"이 상대와 싸우기"},"name":"창귀","sub":"五단계 · 단독 · 권장 스탯 15","desc":"범에게 잡아먹힌 뒤 범의 종이 된 귀신. 다음 먹잇감에게 범을 데려오는 길잡이 노릇을 한다.","lines":["체력 205 · 공격력 22 · 행동력 25 · 영력 18","영능력 [범 부르기] 어디선가 범을 불러들인다. 약해진 사람일수록 더 크게 물린다."]},{"play":{"to":"battle/myogwi","label":"이 상대와 싸우기"},"name":"묘귀","sub":"五단계 · 단독 · 권장 스탯 15","desc":"아홉 번 죽고 아홉 번 되살아났다는 고양이 귀신. 소리 없이 다가와 순식간에 할퀸다.","lines":["체력 218 · 공격력 29 · 행동력 20 · 영력 18","영능력 [할퀸 상처] 깊게 할퀴어 상처를 남긴다. 이번 싸움 동안 최대 체력이 줄어든다."]},{"play":{"to":"battle/jeokwi","label":"이 상대와 싸우기"},"name":"저퀴","sub":"五단계 · 단독 · 권장 스탯 15","desc":"사람 몸에 붙어 병을 옮기는 귀신. 한 번 들러붙으면 쉽게 떨어지지 않는다.","lines":["체력 286 · 공격력 23 · 행동력 18 · 영력 24","영능력 [병 옮기기] 병을 옮긴다. 한동안 받는 피해가 늘고 인내로 버티지 못한다."]},{"play":{"to":"battle/agwi","label":"이 상대와 싸우기"},"name":"아귀 떼","sub":"五단계 · 파티 · 권장 스탯 15","desc":"목구멍이 바늘구멍만 해 아무리 먹어도 배가 차지 않는 굶주린 귀신들. 산 사람의 기운까지 먹어 치운다.","lines":["체력 851 · 공격력 29 · 행동력 16 · 영력 18","영능력 [약한 자부터] 굶주린 아귀들이 가장 약한 사람에게 몰려든다. 막을 수 없다."]},{"play":{"to":"battle/geumdwaeji","label":"이 상대와 싸우기"},"name":"금돼지","sub":"五단계 · 보스 · 권장 스탯 15","desc":"땅속 굴에 사는 금빛 돼지. 사람을 잡아가 굴에 가두며, 금붙이라면 눈이 뒤집힌다.","lines":["체력 1756 · 공격력 55 · 행동력 18 · 영력 18","영능력 [엄니 갈기] 엄니를 갈며 숨을 고른다. 다음 행동은 세 배로 들이받는 강공이다.","영능력 [금빛 울림] 온몸의 금털을 떨어 굴을 울린다. 한동안 의지력이 드는 모든 행동이 두 배로 비싸다."]},{"play":{"to":"battle/gildal","label":"이 상대와 싸우기"},"name":"길달","sub":"六단계 · 단독 · 권장 스탯 18~20","desc":"비형랑이 부리던 귀신 무리에서 달아나 여우로 둔갑했다는 자. 몰리면 모습을 바꿔 숨을 돌린다.","lines":["체력 237 · 공격력 26 · 행동력 31 · 영력 23","영능력 [여우 둔갑] 여우로 둔갑해 몸을 감춘다. 다음 일반 공격 두 번을 흘려 낸다."]},{"play":{"to":"battle/jigwi","label":"이 상대와 싸우기"},"name":"지귀","sub":"六단계 · 단독 · 권장 스탯 18~20","desc":"이룰 수 없는 사랑에 가슴이 타 버려 불귀신이 된 사내. 그가 지나간 자리엔 불씨가 남는다.","lines":["체력 238 · 공격력 34 · 행동력 24 · 영력 23","영능력 [연모의 불길] 가슴의 불길이 옮겨붙는다. 한동안 앞뒤 가리지 않고 일반 공격만 하게 된다."]},{"play":{"to":"battle/gawi-gwi","label":"이 상대와 싸우기"},"name":"가위귀","sub":"六단계 · 단독 · 권장 스탯 18~20","desc":"잠든 사람의 가슴 위에 올라앉아 짓누르는 귀신. 깨어 있어도 그 무게는 똑같다.","lines":["체력 297 · 공격력 27 · 행동력 22 · 영력 30","영능력 [가위눌림] 가슴을 짓눌러 잠재운다. 최대 세 턴 동안 움직일 수 없지만, 아프면 깬다."]},{"play":{"to":"battle/udu-mamyeon","label":"이 상대와 싸우기"},"name":"우두마면","sub":"六단계 · 파티 · 권장 스탯 18~20","desc":"소머리를 한 우두와 말머리를 한 마면. 명부에서 망자를 끌고 가는 두 옥졸이 이승까지 올라왔다.","lines":["체력 1048 · 공격력 27 · 행동력 20 · 영력 23","영능력 [명부 쇠사슬] 명부의 쇠사슬로 한 사람의 넋을 옭아맨다. 막을 수 없고, 이번 싸움에서 버틸 기회를 하나 빼앗는다."]},{"play":{"to":"battle/gumiho","label":"이 상대와 싸우기"},"name":"구미호","sub":"六단계 · 보스 · 권장 스탯 18~20","desc":"천 년을 묵어 꼬리가 아홉 갈래로 갈라진 여우. 사람의 기운을 받아먹을 때마다 잠든 꼬리가 하나씩 깨어난다.","lines":["체력 1789 · 공격력 73 · 행동력 22 · 영력 23","영능력 [여우구슬] 한 사람의 입에 구슬을 밀어 넣어 기운을 빼앗는다. 칠성낙인의 힘과 모으던 도깨비불이 구미호에게 넘어간다.","영능력 [꼬리 하나 태우기] 꼬리 하나를 태워 상처를 아문다."]},{"play":{"to":"battle/yeou-nui","label":"이 상대와 싸우기"},"name":"여우누이","sub":"七단계 · 단독 · 권장 스탯 29~30","desc":"오래 기다려 얻은 막내딸이 실은 여우였다. 밤마다 외양간의 소와 말이 한 마리씩 사라진다.","lines":["체력 302 · 공격력 50 · 행동력 36 · 영력 35","영능력 [누이 얼굴] 다정한 누이의 얼굴로 홀린다. 다음 일반 공격·부적이 나를 향한다."]},{"play":{"to":"battle/noho-seung","label":"이 상대와 싸우기"},"name":"노호승","sub":"七단계 · 단독 · 권장 스탯 29~30","desc":"스님의 탈을 쓰고 경을 외는 늙은 여우. 그 독경을 들으면 몸속의 영력이 굳어 버린다.","lines":["체력 427 · 공격력 37 · 행동력 33 · 영력 45","영능력 [거꾸로 외는 경] 경을 거꾸로 외어 시간을 되감는다. 두 턴 전의 몸으로 돌아간다."]},{"play":{"to":"battle/chokru-gwi","label":"이 상대와 싸우기"},"name":"촉루귀","sub":"七단계 · 단독 · 권장 스탯 29~30","desc":"들판에 버려진 해골들이 서로 엉겨 붙어 일어선 귀신. 부딪칠 때마다 뼈 소리가 요란하다.","lines":["체력 471 · 공격력 31 · 행동력 29 · 영력 35","영능력 [뼈 맞추기] 흩어진 뼈를 미리 맞춰 둔다. 쓰러져도 한 번은 다시 일어선다."]},{"play":{"to":"battle/bulgae","label":"이 상대와 싸우기"},"name":"불개","sub":"七단계 · 파티 · 권장 스탯 29~30","desc":"어둠의 나라 까막나라 임금이 해와 달을 훔쳐 오라고 보낸 개. 해를 물면 입이 데고, 달을 물면 이가 시려 놓아 버린다.","lines":["체력 1313 · 공격력 35 · 행동력 46 · 영력 35","영능력 [해와 달 물기] 해를 물고 달을 문다. 한 사람에게서 다음 사람으로 옮겨 가며 물수록 힘이 빠진다."]},{"play":{"to":"battle/yeoksin","label":"이 상대와 싸우기"},"name":"역신","sub":"七단계 · 보스 · 권장 스탯 29~30","desc":"사람 사는 마을마다 돌림병을 퍼뜨리는 귀신. 병이 번질수록 그 몸집도 함께 불어난다.","lines":["체력 2907 · 공격력 53 · 행동력 33 · 영력 35","영능력 [역병] 한 사람에게 역병을 옮긴다. 라운드가 끝날 때마다 몸이 상하고, 안 걸린 사람에게 번진다.","영능력 [돌림병] 일행 전원에게 병을 돌린다. 한동안 어떤 회복도 듣지 않는다."]},{"play":{"to":"battle/geuseunsae","label":"이 상대와 싸우기"},"name":"그슨새","sub":"八단계 · 단독 · 권장 스탯 39~40","desc":"그슨대가 새의 모습을 한 것이라고도 한다. 커다란 날개로 사람을 덮어 앞을 보지 못하게 한다.","lines":["체력 485 · 공격력 46 · 행동력 43 · 영력 60","영능력 [날개 덮기] 커다란 날개로 하늘을 덮는다. 한동안 앞이 보이지 않아 공격이 자주 빗나간다."]},{"play":{"to":"battle/hwama","label":"이 상대와 싸우기"},"name":"화마","sub":"八단계 · 단독 · 권장 스탯 39~40","desc":"불길 속에서 태어나 불길로 사는 마귀. 집 한 채를 삼키는 데 숨 한 번이면 족하다.","lines":["체력 467 · 공격력 67 · 행동력 47 · 영력 46","영능력 [번지는 불] 불길을 옮겨붙인다. 내 턴마다 몸이 타고, 웅크려야 꺼진다."]},{"play":{"to":"battle/yeongno","label":"이 상대와 싸우기"},"name":"영노","sub":"八단계 · 단독 · 권장 스탯 39~40","desc":"사람 아흔아홉을 잡아먹고 하나만 더 먹으면 하늘에 오른다는 괴물. 그 하나가 누구일지 늘 고르고 있다.","lines":["체력 703 · 공격력 43 · 행동력 38 · 영력 46","영능력 [아흔아홉째] 아흔아홉을 먹고 백을 채우려 한다. 막을 수 없고, 쓸 때마다 다음 피해가 두 배로 커진다."]},{"play":{"to":"battle/yacha-nachal","label":"이 상대와 싸우기"},"name":"야차나찰","sub":"八단계 · 파티 · 권장 스탯 39~40","desc":"하늘을 나는 야차와 사람을 먹는 나찰. 한 쌍의 칼처럼 붙어 다니며 동시에 덤벼든다.","lines":["체력 1601 · 공격력 66 · 행동력 59 · 영력 46","영능력 [쌍칼 쳐내기] 쌍칼로 일행의 무구를 쳐낸다. 한동안 무구 효과와 특수 강화가 꺼진다."]},{"play":{"to":"battle/hanbal","label":"이 상대와 싸우기"},"name":"한발","sub":"八단계 · 보스 · 권장 스탯 39~40","desc":"그가 나타나면 비가 그치고 강이 마른다는 가뭄의 마귀. 마른 땅에서 사람의 물기까지 빨아들인다.","lines":["체력 4278 · 공격력 90 · 행동력 43 · 영력 46","영능력 [목마름] 한 사람의 물기를 말린다. 한동안 의지력을 쓸 때마다 같은 양의 체력이 깎인다.","영능력 [가뭄의 해] 땡볕을 내리쬔다. 라운드가 끝날 때마다 일행이 타들어 가고, 충분히 때려야 비가 온다."]},{"play":{"to":"battle/gangcheol","label":"이 상대와 싸우기"},"name":"강철이","sub":"九단계 · 단독 · 권장 스탯 45~47","desc":"용이 되다 만 괴수. 지나가는 곳마다 가을 들판이 하룻밤 새 말라 버려 '강철이 간 데는 가을도 봄'이라는 말이 생겼다.","lines":["체력 598 · 공격력 60 · 행동력 49 · 영력 54","영능력 [마른 바람] 메마른 바람이 의지력을 태운다. 태운 만큼 몸이 다친다."]},{"play":{"to":"battle/mudu-gwi","label":"이 상대와 싸우기"},"name":"무두귀","sub":"九단계 · 단독 · 권장 스탯 45~47","desc":"머리 없이 떠도는 귀신. 잃어버린 머리를 찾아 닥치는 대로 붙잡는다.","lines":["체력 535 · 공격력 77 · 행동력 54 · 영력 54","영능력 [머리 찾기] 머리 없는 몸이 덥석 붙잡는다. 막을 수 없고, 공포에 질려 다음 턴엔 공격하지 못한다."]},{"play":{"to":"battle/gwimok","label":"이 상대와 싸우기"},"name":"귀목","sub":"九단계 · 단독 · 권장 스탯 45~47","desc":"사람의 피를 빨아 천 년을 자란 고목. 뿌리가 닿는 곳마다 풀이 시든다.","lines":["체력 816 · 공격력 50 · 행동력 44 · 영력 54","영능력 [껍질 두르기] 두꺼운 껍질을 두른다. 껍질이 깨질 때까지 피해를 대신 받는다."]},{"play":{"to":"battle/baekgwi","label":"이 상대와 싸우기"},"name":"백귀행렬","sub":"九단계 · 파티 · 권장 스탯 45~47","desc":"깊은 밤 길을 지나가는 백 가지 귀신의 행렬. 마주친 사람은 행렬에 끼어 함께 걷게 된다.","lines":["체력 2187 · 공격력 61 · 행동력 49 · 영력 70","영능력 [행렬에 끼우기] 한 사람을 행렬에 끌고 간다. 두 라운드 동안 싸움에서 빠지지만, 남은 일행이 크게 때리면 돌아온다."]},{"play":{"to":"battle/samdugumi","label":"이 상대와 싸우기"},"name":"삼두구미","sub":"九단계 · 보스 · 권장 스탯 45~47","desc":"머리가 셋, 꼬리가 아홉 달린 괴물. 무덤을 파헤쳐 송장을 먹으며, 세 머리가 서로 상처를 핥아 준다.","lines":["체력 4173 · 공격력 58 · 행동력 49 · 영력 54","영능력 [세 머리] 세 머리가 차례로 한 사람을 문다. 막을 수 없다.","영능력 [꼬리에 감은 원한] 아홉 꼬리에 감아 둔 원한을 풀어 놓는다. 최근 두 라운드 동안 받은 피해를 모아 일행에게 되돌린다."]},{"play":{"to":"battle/baekgol-janggun","label":"이 상대와 싸우기"},"name":"백골장군","sub":"十단계 · 단독 · 권장 스탯 50","desc":"옛 싸움터의 백골이 녹슨 갑옷을 걸치고 일어섰다. 북소리가 울리면 부서진 뼈도 다시 맞붙는다.","lines":["체력 778 · 공격력 51 · 행동력 48 · 영력 58","영능력 [방패 진형] 백골 병사들이 방패를 겹겹이 세운다. 다음 공격의 피해 절반이 되돌아온다."]},{"play":{"to":"battle/yohwa","label":"이 상대와 싸우기"},"name":"요화","sub":"十단계 · 단독 · 권장 스탯 50","desc":"무덤가에 피어 망자의 피를 먹고 자란 핏빛 꽃. 그 꽃가루를 들이마시면 넋이 흐려진다.","lines":["체력 769 · 공격력 65 · 행동력 53 · 영력 76","영능력 [저린 꽃가루] 저린 꽃가루를 흩뿌린다. 한동안 몸이 저려 고른 행동이 실패하곤 한다."]},{"play":{"to":"battle/daein","label":"이 상대와 싸우기"},"name":"대인","sub":"十단계 · 단독 · 권장 스탯 50","desc":"구름 위로 머리가 솟는 거인. 걸음 한 번에 산 하나를 넘고, 발을 디딜 때마다 땅이 꺼진다.","lines":["체력 777 · 공격력 94 · 행동력 58 · 영력 58","영능력 [발 들어 올리기] 산만 한 발을 들어 올린다. 세 턴 뒤 내리찍지만, 그 사이 크게 때리면 넘어진다."]},{"play":{"to":"battle/gunggi","label":"이 상대와 싸우기"},"name":"궁기","sub":"十단계 · 파티 · 권장 스탯 50","desc":"날개 달린 범의 모습을 한 흉수. 싸움을 말리는 자를 먼저 잡아먹고, 거짓말하는 자에게는 짐승을 잡아 바친다.","lines":["체력 2162 · 공격력 38 · 행동력 74 · 영력 58","영능력 [싸움 붙이기] 일행 사이에 싸움을 붙인다. 두 사람이 서로를 친다."]},{"play":{"to":"battle/jihaguk-daejeok","label":"이 상대와 싸우기"},"name":"지하국 대적","sub":"十단계 · 보스 · 권장 스탯 50","desc":"땅 밑 나라를 다스리는 머리 아홉 달린 도적. 땅 위의 사람을 잡아다 땅속에 가두고, 잘린 머리도 다시 돋아난다.","lines":["체력 4657 · 공격력 71 · 행동력 53 · 영력 58","영능력 [머리 떼어 던지기] 제 머리 하나를 떼어 던진다. 자기 체력을 깎아 그 세 배로 친다.","영능력 [아홉 머리 깨우기] 잠든 머리를 하나 더 깨운다. 쓸 때마다 공격력이 쌓여 오른다."]},{"play":{"to":"battle/cheonma","label":"이 상대와 싸우기"},"name":"천마","sub":"10단계 · 단독 · 권장 스탯 60","desc":"하늘 끝에 산다는 마왕. 수행하는 자의 앞을 가로막고, 깨달음에 가까운 자일수록 더 크게 흔든다.","lines":["체력 922 · 공격력 109 · 행동력 69 · 영력 70","영능력 [마왕의 거울] 마왕의 거울에 나를 비춘다. 한동안 내 가장 강한 힘을 빌려 공격력이 오른다."]},{"play":{"to":"battle/doul","label":"이 상대와 싸우기"},"name":"도올","sub":"10단계 · 단독 · 권장 스탯 60","desc":"사람의 말을 듣지 않고 길들일 수도 없다는 흉수. 범의 몸에 사람의 얼굴, 멧돼지의 엄니를 가졌다.","lines":["체력 1309 · 공격력 70 · 행동력 57 · 영력 70","영능력 [날뛰기] 미쳐 날뛴다. 다음 세 번의 행동이 모두 강공이다."]},{"play":{"to":"battle/geoul-gwi","label":"이 상대와 싸우기"},"name":"거울귀","sub":"10단계 · 단독 · 권장 스탯 60","desc":"무당의 청동거울에 깃든 귀신. 거울에 비친 기운을 그대로 빼앗아 제 것으로 삼는다.","lines":["체력 1472 · 공격력 89 · 행동력 63 · 영력 91","영능력 [되비추기] 거울이 나와 저를 되비춘다. 둘의 체력 비율이 평균으로 맞춰진다."]},{"play":{"to":"battle/hondon","label":"이 상대와 싸우기"},"name":"혼돈","sub":"10단계 · 파티 · 권장 스탯 60","desc":"눈도 코도 입도 귀도 없는 흉수. 누군가 일곱 구멍을 뚫어 주자 이레 만에 죽었다는데, 다시 태어난 것은 구멍을 거꾸로 뚫는다.","lines":["체력 3076 · 공격력 213 · 행동력 57 · 영력 70","영능력 [일곱 구멍 뒤섞기] 일곱 구멍을 뒤섞어 일행의 기운을 헝클어뜨린다. 한동안 저마다 스탯 두 개가 맞바뀐다."]},{"play":{"to":"battle/docheol","label":"이 상대와 싸우기"},"name":"도철","sub":"10단계 · 보스 · 권장 스탯 60","desc":"먹는 것밖에 모르는 흉수. 무엇이든 삼키다 끝내 제 몸뚱이까지 먹어 치워 머리만 남았다. 그래도 허기는 끝나지 않는다.","lines":["체력 6541 · 공격력 250 · 행동력 63 · 영력 70","영능력 [결계째 삼키기] 한 사람의 영력결계를 통째로 삼킨다. 막을 수 없고, 결계는 이번 싸움에서 다시 서지 않는다.","영능력 [끝없는 허기] 일행이 지닌 부적을 모두 먹어 치우고, 먹은 만큼 살이 오른다."]}]},{"id":"hike","title":"산 탐사","kind":"scene","root":{"id":"hike","name":"뒷산","choices":[{"id":"left","name":"왼길","choices":[{"id":"armory","name":"무구보관소","text":[{"t":"학교가 수시로 철통같이 감시하고 있는 무구들의 창고(어떻게 감시하길래 누가 몰래 들어갈 때마다 귀신같이 알아채는지는 아무도 모른다). 자신이 정식으로 학교에 승인을 받은 무구가 아니면 사용할 수 없는 것이 원칙이지만, 날을 갈고 무기를 꾸미는 정도의 행동은 자유롭게 할 수 있도록 허락되어 있다."}],"choices":[{"id":"armoryManage","name":"무구 관리하기","play":{"to":"armory","label":"무구 관리하기"}}]},{"id":"garden","name":"텃밭","text":[{"t":"고랑 사이로 쑥과 이름표를 단 어린 싹들이 자라고 있다. 어느 고랑은 누가 봐도 반듯하고 어느 고랑은 누가 봐도 지옥에서 기어올라온 듯한 풀이 자라고 있다. 성격이 자유자재로 드러나는 텃밭들이다."}],"choices":[{"id":"seedShop","name":"씨앗 상점","text":[{"t":"씨앗 상점 주인이 종자를 맡고 있는 곳. 학생들에게 소정의 돈을 받고 씨앗을 팔며, 텃밭을 관리하는 걸 도와준다."}],"play":{"to":"garden","label":"씨앗 상점 열기"}},{"id":"greenhouse","name":"비닐하우스","play":{"to":"garden","label":"비닐하우스 열기"}}]},{"id":"goblinFarm","name":"도깨비 농장","text":[{"t":"도깨비들이 손을 보태는 별난 농장. 농사가 쉬워졌는지는 모르겠지만, 어째 수확은 점점 더 어려워지고 있는 건 기분 탓일까? 갈 수록 누군가들의 ‘장난’이 많아지고 있는 탓일지도 모른다."},{"t":"농장은 걸어다니는 사람이 없다. 그저 수많은 오래된 물건들이 잡다하게 놓여 있을 뿐이다. 그것들은 당신이 고개를 돌리면 위치가 바뀌어 있고, 머뭇거리는 동안 무언가를 이루어 놓는다. 당신이 당황하는 모습을 보며 저들끼리 낄낄대며 즐거워한다. 한 숨 돌리면 어느새 당신의 주머니가 비어 있을지도 모른다. 그럴 때에는 도깨비님, 도깨비님 하며 싹싹 빌어야 한다."}],"choices":[{"id":"farming","name":"농사 짓기","text":[{"t":"일용할 양식을 도깨비님께 조금씩 바쳐가며 빌어 보자."}]},{"id":"ricePouch","name":"볍씨 주머니 열기","widgetNote":"볍씨 주머니는 아직 화면에 연결되지 않았다."},{"id":"goblinPlay","name":"도깨비들과 놀아주기","notice":"한 번 놀아줄 때마다 10분을 기다리거나, [빠른 놀이]로 의지력 5를 쓴다. 이긴 보상(도깨비 증표 1개)은 하루에 한 번만 받는다.","widgetNote":"오늘의 도깨비 놀이는 아직 화면에 연결되지 않았다.","choices":[{"id":"goblin-ssireum","name":"씨름","result":["승리 : 당신은 힘껏 커다란 장롱을 넘겼다. 장롱이 투덜거린다.\n패배 : 당신은 장롱에게 가볍게 넘겨졌다. 등이 흙으로 엉망이 된 모습에 도깨비들이 낄낄거린다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."},{"id":"goblin-wordChain","name":"끝말잇기","result":["승리 : 당신은 낡은 사전과 한참 말씨름을 한 끝에 어떻게든 꼬투리를 잡아 보았다. 사전이 한 수 봐준 듯한 건 착각이겠지? \n패배 : 사람이 책을 어떻게 이겨? 도깨비는 친절한 말투로 김서방치고는 힘냈다고 위로해준다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."},{"id":"goblin-tag","name":"술래잡기","result":["승리 : 당신은 바람처럼 달리던 수레바퀴를 잡아 멈춰 세웠다. 바퀴는 승부의 결과를 받아들였다.\n패배 : 당신은 빠르게 달려나가는 수레를 따라 달리다가, 흙먼지를 맞고 넘어지고 말았다. 다치진 않았지만 자존심이 상했다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."},{"id":"goblin-hideSeek","name":"숨바꼭질","result":["승리 : 당신은 돌부리 구석에 몸을 숨긴 낡은 숟가락을 간신히 찾아냈다. 숟가락이 펄쩍 뛰며 놀란다.\n패배 : 당신은 곳곳에 숨은 자그마한 물건들을 다 찾기는 커녕 하나도 간신히 발견해야 했다. 당신을 놀리듯 시간이 끝나자마자 여기저기서 작은 물건들이 튀어오른다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."},{"id":"goblin-gonggi","name":"공기놀이","result":["승리 : 당신은 공깃돌을 제 수족처럼 다루며 승리를 따내었다. 어린 도깨비들은 승부도 잊고 신기하게 당신을 구경했다.\n패배 : 당신의 상대 도깨비는 공깃돌을 제 수족처럼 다루며 승리를 따내었다. 당신은 승부도 잊고 그것을 구경해야 했다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."},{"id":"goblin-yut","name":"윷놀이","result":["승리 : 당신은 반칙이라며 주변에서 마구 구시렁대는 옷가지들을 무시하고 승리를 만끽한다.\n패배 : 당신의 승부 상대였던 천 옷가지들이 윷을 둘둘 감으며 승리를 만끽한다."],"cost":{"mp":5,"wait":10},"widgetNote":"이 선택의 결과(판정 · 보상)는 아직 화면에 연결되지 않았다."}]}]},{"id":"beastGround","name":"신수들의 터","text":[{"t":"신수들이 산기슭에서 쉬거나 드나드는 터. 주인을 정할 수 없는 생명들이니 그들의 거리를 존중하는 것이 첫 번째 예절이다. 서로를 존중하다 보면 아직 어린 신수들이 내려와 당신들의 발치를 기웃거리는 때도 생긴다. 데리고 있는 존재가 있다면 함께 뛰놀게 할 수도 있다."},{"t":"수많은 시선이 느껴진다. 당신이 한 발을 옮길 때마다 주시하고 있다. 평범한 숲에 울타리를 둘러 공간을 나눴을 뿐인 곳처럼 보이지만, 사실 이 안에는 많은 ‘것’들이 존재하고 있다. 당신이 감지할 수 없을 뿐이다."}],"choices":[{"id":"beastKeep","name":"신수 맡기기","notice":"아직 만들어지지 않은 시스템"}]}]},{"id":"center","name":"중앙길","choices":[{"id":"climb","name":"산 오르기","choices":[{"id":"peak","name":"산꼭대기","text":[{"t":"마지막 돌계단을 오르자 시야가 갑자기 트인다. 건물들은 손바닥만 하게 보이고, 호수는 그 너머에서 둥글게 빛난다. 숨은 차오르지만 발걸음을 멈출 만한 풍경이다. 이런 곳까지 기어오르지 않으면 여유를 찾을 수 없다니, 새삼스럽게 얼마나 대단한 비일상을 보내고 있는지 체감이 된다."}],"choices":[{"id":"meditate","name":"명상하기","text":[{"t":"이곳은 창록교와 청화읍을 굽어보는 산의 가장 높은 곳. 올라오는 동안 놓친 생각들이 여기서는 조금 선명해질지도 모른다."}],"notice":"[아직 메인 스토리가 시작되지 않았습니다]"}]},{"id":"temple","name":"사찰","text":[{"t":"산속에서 오랫동안 자리를 지켜 온 작은 사찰. 신령과 귀신을 배우는 학교 곁에 불경 소리가 이어지는 것도 그리 낯선 일은 아니다. 우리는 들어갈 수 없는 공간이라고 알려진 곳이기 이전에, 애초에 어째서인지 저 안으로 들어가고 싶다는 기분조차 들지 않는다."},{"t":"저 안에 누가 살고 있는 것일까? 종종 목탁을 치는 소리와 불경을 읊는 목소리가 들리니 사람이 있는 것은 확실하지만 당신들은 저 안에 사는 이들과 교류는 커녕 사찰에 사는 사람들의 그림자조차 마주해본 적이 없다. 어쩌면 그 자체가 당신들을 홀리는 환청일지도 모르고."}]},{"id":"tomb","name":"묘소","text":[{"t":"산에 잠든 이들을 위한 묘소. 오래된 이름 앞에서는 누가 먼저 왔는지보다 누가 기억하고 있는지가 더 중요하다. \n*헤집어라. 뒤엎어라. 들쑤셔라. 잔치를 벌여라. 네가 ****너****라는 사실을 망자들에게 들키지 말라.*"},{"t":"고요한 묘소 주변으로 새파랗고 작은 불들이 둥둥 떠다닌다. 이 도깨비불은 과학적으로 증명이 되어 있다며 세간의 사람들은 수군수군 떠들어대지만, 당신들은 알고 있다. 이것은 단순한 상식으로 설명되는 존재들이 아니라는 것을."}]},{"id":"mysteryStorage","name":"?? 보관소","text":[{"t":"앞 글자가 제대로 읽히지 않는 보관소. 누가 무엇을 숨겨 두었는지 모를 때에는, 모른다는 사실을 기억하는 편이 안전하다. 미치지 않고 싶다면야, 주변의 모든 것들이 낡아 있는데 자물쇠만 새 것 같다는 사실이라던가, 퀴퀴하게 올라오는 냄새 사이로 배인 흙내음의 포근함이라던가, 그런 것들은 잊어버리는 게 낫다."}]}]},{"id":"loop","name":"둘레길","text":[{"t":"저 너머로 가면 이 학교를 떠나 소위 말하는 속세로 돌아갈 수 있다. 사람들이 바글바글하고 떠들썩하게 놀 수 있는 곳. 하지만 그곳은 무속의 길을 걷는 이들에게 허락되지 않았다. 아직 당신들에게는 도리어 위험한 곳이다."}],"choices":[{"id":"outside","name":"교외","text":[{"t":"나무가 그득한 산길 너머, 산 아래로 익숙한 교외의 풍경이 보인다. 교문이랄 게 없는 이 폐쇄된 학교에서 유일하게 밖으로 나가는 길이다. 밖으로 나가고 싶어도 허공을 가로막는 붉은 줄들이 당신의 눈앞을 현혹시킨다. 그것을 보는 것만으로도 발걸음이 왠지 떨어지지 않는다."}],"widgetNote":"교문 밖은 짙은 안개에 잠겨 있다."},{"id":"extraBattle","name":"추가전투","play":{"to":"extra/1","label":"추가전투 시작"}}]}]},{"id":"right","name":"오른길","choices":[{"id":"river","name":"청화강","text":[{"t":"산과 학교의 풍경을 잇는 청화강. 물은 늘 아래로 흐르지만 그 아래에서 무엇이 위를 올려다보는지는 알 수 없다. 가끔 어마어마하게 커다란 그림자가 지나다니며 부주의하게 발을 담근 학생들을 깜짝 놀래킨다. 그러면 학생들은 혼비백산해 본관으로 도망친다."},{"t":"강과 계곡, 호수는 하나의 선처럼 이어져 있다. 가끔 나사 빠진 애들이 뗏목 같은 걸 만들어서 타고 다니기도 하는데, 학교에서는 그 정도는 눈감아주고 있는 것 같다. 가끔 수살귀 같은 것들과 마주하긴 하지만, 그 정도도 못 처리하면 이 학교 학생이 아니니까."}]},{"id":"lake","name":"청화호수","text":[{"t":"청화강과 이어진 넓은 호수. 잔잔한 수면을 보고 있으면 산이 거꾸로 한 번 더 자라고 있다는 생각이 든다. 그런 생각에 빠져 있다 보면 당신은 수면에 비친 당신의 얼굴이 웃고 있는 것을 발견한다. 까딱하면 물귀신이 될 뻔했다. 당신은 펄쩍 뒤로 물러난다."},{"t":"청화호수는 평상시에는 고요한 곳이다. 돌을 던지거나, 낚시를 하는 등의 행동을 하며 놀 수도 있겠지만 권장하지는 않는다. 그 안에 있는 것들이 당신에게 호의적이리란 보장은 없으니까."}]},{"id":"campsite","name":"캠핑장","text":[{"t":"항상 등불이 밝혀져 있는 캠핑장. 동그랗게 쌓인 돌 사이에 식은 잿더미가 남아 있다. 천막 자리에는 풀이 납작하게 눌려 있고, 나뭇가지에는 사용 안내가 매달려 있다. 기숙사에서 잠들기가 지루한 학생들은 이곳에 와서 잠들기도 하지만, 반드시 선생님의 허락을 맡아야 한다. 밤에는 야영지 지킴이가 항상 이 공간을 지키고 있다."}]}]},{"id":"yard","name":"퇴마 실습장","text":[{"t":"넓은 흙바닥에 원형 표식과 발자국이 겹쳐 있다. 가장자리에는 훈련용 부적과 보호 장비가 정리돼 있다. 멀리서 기합 소리가 들린다. 아니, 비명 소리인가? 아무튼 누군가는 오늘도 절찬리에 넘어지는 법부터 배우고 있는 모양이다."},{"t":"과열되기 쉬운 분위기를 가라앉히기 위해 준비된 허수아비는 주로 당일에 망가지고 만다. 볏짚을 다시 쌓아올리는 선생님들의 한숨 섞인 목소리는 열을 띈 학생들의 목소리에 오늘도 묻혀만 간다."}],"note":"퇴마 실습은 위쪽 활동 칸의 [퇴마 실습]에서 할 수 있다."}]}},{"id":"pioneer","title":"개척","kind":"list","intro":"개척 터 23곳. 10×10 칸을 움직이며 채집 · 수렵한다.","play":{"to":"pioneer","label":"개척 열기"},"items":[{"play":{"to":"pioneer/left-trail-1","label":"이 터로 개척 나가기"},"name":"산길-1","sub":"30턴 · 칸 13개","desc":"","lines":["식물: 쑥, 독버섯, 뱀딸기, 버섯","장애물: 돌탑, 바위 기둥, 덤불","동물: 뱀, 너구리","영물: 부러진 장승 (20%)","요괴: 산귀신"]},{"play":{"to":"pioneer/left-trail-2","label":"이 터로 개척 나가기"},"name":"산길 2","sub":"30턴 · 칸 13개","desc":"","lines":["식물: 토끼풀, 민들레, 버섯, 독버섯","장애물: 거대 버섯 군락, 바위 기둥, 덤불","동물: 고라니, 멧비둘기","영물: 부러진 장승 (15%)","요괴: 산귀신"]},{"play":{"to":"pioneer/left-trail-3","label":"이 터로 개척 나가기"},"name":"산길 3","sub":"30턴 · 칸 15개","desc":"","lines":["동물: 토끼","식물: 산삼, 고사리, 진달래, 상추, 취나물","장애물: 자갈더미, 폐우물","영물: 청록사슴 (15%)","요괴: 목신"]},{"play":{"to":"pioneer/left-trail-4","label":"이 터로 개척 나가기"},"name":"산길 4","sub":"30턴 · 칸 13개","desc":"","lines":["장애물: 덤불, 솟대","식물: 토끼풀 덤불, 소나무, 감초 터, 버드나무","동물: 멧돼지, 여우","영물: 청록사슴 (15%)","요괴: 목신"]},{"play":{"to":"pioneer/left-lake","label":"이 터로 개척 나가기"},"name":"호수","sub":"30턴 · 칸 12개","desc":"","lines":["동물: 잉어","장애물: 용왕제단, 물길 바위, 물","식물: 물가 풀숲, 이끼바위, 웅덩이","영물: 이무기 (15%)","요괴: 물귀신"]},{"play":{"to":"pioneer/left-cemetery","label":"이 터로 개척 나가기"},"name":"묘소","sub":"30턴 · 칸 21개","desc":"","lines":["동물: 들쥐","장애물: 돌탑, 장명등, 혼유석, 봉인된 석관, 향로석, 망주석","영물: 혼백나비 (15%)","요괴: 앙괭이"]},{"play":{"to":"pioneer/left-cave","label":"이 터로 개척 나가기"},"name":"동굴","sub":"30턴 · 칸 16개","desc":"","lines":["장애물: 동물 유해, 제단, 수정기둥, 종유석, 봉인된 석문","동물: 박쥐","식물: 달꽃터","영물: 암령 (15%)","요괴: 어둑시니"]},{"play":{"to":"pioneer/left-trail-5","label":"이 터로 개척 나가기"},"name":"산길 5","sub":"30턴 · 칸 18개","desc":"","lines":["식물: 참나무, 밤나무, 고사리, 버섯","장애물: 덤불, 거대 버섯 군락","동물: 다람쥐, 꿩","영물: 흰 까치 (15%)","요괴: 묵은 원귀"]},{"play":{"to":"pioneer/left-trail-6","label":"이 터로 개척 나가기"},"name":"산길 6","sub":"30턴 · 칸 21개","desc":"","lines":["장애물: 칡덩굴, 바위 기둥","식물: 더덕, 산삼, 도라지, 진달래, 취나물","동물: 오소리, 꿩","영물: 흰 까치 (15%)","요괴: 허깨비"]},{"play":{"to":"pioneer/left-trail-7","label":"이 터로 개척 나가기"},"name":"산길 7","sub":"30턴 · 칸 21개","desc":"","lines":["식물: 소나무, 감초 터, 고사리, 진달래","장애물: 금줄 친 당산나무, 서낭당 돌무더기","동물: 고라니, 너구리","영물: 금두꺼비 (15%)","요괴: 손각시"]},{"play":{"to":"pioneer/left-trail-8","label":"이 터로 개척 나가기"},"name":"산길 8","sub":"30턴 · 칸 17개","desc":"","lines":["식물: 참나무, 소나무, 밤나무, 버드나무","장애물: 숯가마","동물: 오소리, 토끼","영물: 금두꺼비 (15%)","요괴: 창귀"]},{"play":{"to":"pioneer/left-trail-9","label":"이 터로 개척 나가기"},"name":"산길 9","sub":"30턴 · 칸 21개","desc":"","lines":["식물: 당귀, 도라지, 더덕, 산삼, 감초 터","장애물: 바위 기둥","동물: 고라니, 꿩","영물: 산삼 동자 (15%)","요괴: 묘귀"]},{"play":{"to":"pioneer/left-trail-10","label":"이 터로 개척 나가기"},"name":"산길 10","sub":"30턴 · 칸 19개","desc":"","lines":["장애물: 물","식물: 머루 넝쿨, 물가 풀숲, 오미자 덩굴","동물: 수달, 너구리","영물: 산삼 동자 (15%)","요괴: 길달"]},{"play":{"to":"pioneer/left-trail-11","label":"이 터로 개척 나가기"},"name":"산길 11","sub":"30턴 · 칸 19개","desc":"","lines":["식물: 소나무, 참나무, 진달래","장애물: 자갈더미, 벼락 맞은 대추나무","동물: 꿩, 멧돼지","영물: 흰 족제비 (15%)","요괴: 지귀"]},{"play":{"to":"pioneer/left-trail-12","label":"이 터로 개척 나가기"},"name":"산길 12","sub":"30턴 · 칸 22개","desc":"","lines":["식물: 잣나무, 오미자 덩굴","장애물: 무너진 성벽","동물: 담비, 꿩","영물: 흰 족제비 (15%)","요괴: 여우누이"]},{"play":{"to":"pioneer/left-trail-13","label":"이 터로 개척 나가기"},"name":"산길 13","sub":"30턴 · 칸 16개","desc":"","lines":["장애물: 마애불, 절터 석탑","식물: 당귀, 이끼바위, 취나물","동물: 매, 담비","영물: 수리부엉이 (15%)","요괴: 노호승"]},{"play":{"to":"pioneer/left-trail-14","label":"이 터로 개척 나가기"},"name":"산길 14","sub":"30턴 · 칸 18개","desc":"","lines":["식물: 소나무, 잣나무, 송이","장애물: 쓰러진 고목","동물: 담비, 다람쥐","영물: 수리부엉이 (15%)","요괴: 그슨새"]},{"play":{"to":"pioneer/left-trail-15","label":"이 터로 개척 나가기"},"name":"산길 15","sub":"30턴 · 칸 15개","desc":"","lines":["식물: 진달래, 취나물","장애물: 봉수대, 바위 기둥","동물: 매, 멧돼지","영물: 학 (15%)","요괴: 화마"]},{"play":{"to":"pioneer/left-trail-16","label":"이 터로 개척 나가기"},"name":"산길 16","sub":"30턴 · 칸 15개","desc":"","lines":["식물: 당귀, 이끼바위","장애물: 동물 유해","동물: 늑대","영물: 학 (15%)","요괴: 강철이"]},{"play":{"to":"pioneer/left-trail-17","label":"이 터로 개척 나가기"},"name":"산길 17","sub":"30턴 · 칸 17개","desc":"","lines":["장애물: 폭포, 물길 바위","식물: 물가 풀숲, 이끼바위","동물: 수달, 잉어","영물: 흰 노루 (15%)","요괴: 귀목"]},{"play":{"to":"pioneer/left-trail-18","label":"이 터로 개척 나가기"},"name":"산길 18","sub":"30턴 · 칸 18개","desc":"","lines":["장애물: 너덜바위","식물: 잣나무, 송이","동물: 반달가슴곰, 담비","영물: 용마 (15%)","요괴: 백골장군"]},{"play":{"to":"pioneer/left-trail-19","label":"이 터로 개척 나가기"},"name":"산길 19","sub":"30턴 · 칸 16개","desc":"","lines":["식물: 얼음꽃, 솜다리","장애물: 얼음 폭포","동물: 산양","영물: 용마 (15%)","요괴: 대인"]},{"play":{"to":"pioneer/left-trail-20","label":"이 터로 개척 나가기"},"name":"산길 20","sub":"30턴 · 칸 17개","desc":"","lines":["장애물: 산마루 돌탑","식물: 솜다리, 얼음꽃","동물: 산양, 매","영물: 천년 거북 (15%)","요괴: 천마"]}]},{"id":"armory","title":"무구보관소","kind":"list","intro":"학교가 수시로 철통같이 감시하고 있는 무구들의 창고(어떻게 감시하길래 누가 몰래 들어갈 때마다 귀신같이 알아채는지는 아무도 모른다). 자신이 정식으로 학교에 승인을 받은 무구가 아니면 사용할 수 없는 것이 원칙이지만, 날을 갈고 무기를 꾸미는 정도의 행동은 자유롭게 할 수 있도록 허락되어 있다.","play":{"to":"armory","label":"무구 강화하기"},"items":[{"name":"부채","sub":"무구","desc":"옛 선조들의 바람 같은 성정을 그대로 담은, 한지로 만든 줄부채. 학생에 따라 다른 그림이 그려져 있다. 부적처럼 한자를 적는 사람도 적지 않다.","lines":["전투에 돌입할 때 무조건 나 또는 나의 일행이 선공을 가져온다. 또한, 적의 모든 공격 명중률이 (10 + 1d이해)%만큼 줄어든다(아예 빗나간다)."]},{"name":"창","sub":"무구","desc":"삼지창 등 기다란 봉 끝에 날이 달려 앞으로 쭉 내지를 수 있는 무기. 장창의 관통력은 타의 추종을 불허한다.","lines":["매 공격마다 (10 + 호전/2, 내림)% 확률로 치명타. 공격력이 적용되는 영능력·일반 공격·부적·효험에 적용되며, 치명타가 나면 그 공격이 1.5배로 들어간다."]},{"name":"단검","sub":"무구","desc":"호신도, 은장도 등 손에 붙는 짧은 날붙이. 비록 길이는 짧지만 그 존재를 무시해서는 순식간에 목숨이 끊기고 말 것이다.","lines":["상대의 체력이 35% 미만으로 떨어지면 기본 공격력이 1.5배(내림)가 된다."]},{"name":"칼","sub":"무구","desc":"기본형은 허리춤에 차는 환도가 권장되나 언월도, 망나니칼 등 날이 크고 기다란 것을 위험천만하게 다루는 담력 있는 이들도 적지 않다.","lines":["막기에 성공했는지와 상관없이, 적의 공격 대상이 될 때마다 반격한다. (1d호전×2 피해) 이때 막기 중이면서 기존 반격 강화 조건(완전 방어 또는 호전이 상대보다 높음)도 함께 달성하면, 반격 피해가 1d호전×3으로 올라간다."]},{"name":"활","sub":"무구","desc":"한민족의 영혼을 내려받은 국궁용 활. 자유롭게 다룰 수 있도록 탄력이 좋은 소재로 다루어져 있는 것이 기본이나, 다루는 사람에 따라 자유롭게 꾸미기도 한다.","lines":["모든 공격이 반드시 명중한다. (호전)% 확률로 상대의 방어 태세를 무시한다. 단체 전투일 경우 전원에게 적용된다 — 활을 든 사람이 한 명만 있어도 일행 전원이 이 효과를 받는다."]},{"name":"무당방울","sub":"무구","desc":"무당들이 굿을 할 때 쓰는 방울. 방울은 신을 부르기도 쫓기도 다루기도 하며 인간과 삶의 다리를 잇는 무당들의 삶을 그대로 드러내었다.","lines":["버티기를 시도할 수 있는 횟수가 1회 늘어난다. (0이 된 의지력은 자동으로 채워지지 않으며, 의지력이 0이면 두 번째 버티기도 할 수 없다.) 또한 소지자의 매 턴마다 10% 확률로 1d(이해)만큼 같은 파티원 전원(본인 포함)의 체력이 회복된다."]},{"name":"악기","sub":"무구","desc":"예나 지금이나 사람의 마음을 움직일 수 있는 가장 좋은 무구. 꽹과리나 가야금, 장구, 단소 등 그 종류는 다양하다.","lines":["같은 파티원(본인 포함)의 모든 공격 행동 및 막기 반격에 [이해] 값만큼 공격력 보정이 고정으로 붙는다. (더 이상 주사위를 굴리지 않는다) 단, 악기를 든 사람 자신에게 적용될 때는 그 보정의 75%만 적용된다."]},{"name":"낫","sub":"무구","desc":"원래는 풀을 베는 도구였다. 식물의 목숨이나 뺏어야 했을 날붙이가 사람을 향하게 된 역사는 생각 이상으로 복잡하고 길다고 한다.","lines":["전투를 마치고 받는 보상이 1.5배(올림)로 늘어난다."]},{"name":"석장","sub":"무구","desc":"불교에서 수행자들이 사용하는 의식 도구. 깊은 불심을 가진 사람이 주술을 시전하는 데에 도움을 주거나 영능력을 보조하는 데에 쓰인다.","lines":["전투 중 모든 의지력 소모가 20% 줄어든다. (소수점 내림)"]},{"name":"철퇴","sub":"무구","desc":"막대 끝에 무게추가 달린 형태의 무기. 다양한 형태가 하나같이 뛰어난 파괴력을 가졌으나, 그 파괴력을 제어하지 못하면 스스로가 크게 다칠 수 있다.","lines":["모든 기본 공격력이 1.5배(내림)가 된다. 단, 적에게서 받는 모든 공격도 1.5배가 된다."]}]},{"id":"garden","title":"텃밭","kind":"list","intro":"비닐하우스 5칸 · 60분 성장.","play":{"to":"garden","label":"텃밭 가기"},"items":[{"name":"방울토마토","sub":"씨앗 3냥","desc":"손가락 한 마디만큼 작지만 커다란 토마토가 할 수 있는 대부분의 일을 할 수 있다.","lines":[]},{"name":"당근","sub":"씨앗 3냥","desc":"흐물흐물한 당근파와 딱딱한 당근파 사이에서 전쟁이 일어나곤 한다.","lines":[]},{"name":"상추","sub":"씨앗 3냥","desc":"텃밭에서 키우고 있다. 뜯어갈 때는 허락을 구하자.","lines":[]},{"name":"감자","sub":"씨앗 3냥","desc":"대부분의 한식에 빠지면 끔찍한 기분이 드는 필수 뿌리감자.","lines":[]},{"name":"배추","sub":"씨앗 3냥","desc":"포기하지 마. 배추가 항상 대신 포기하고 있다.","lines":[]},{"name":"시금치","sub":"씨앗 3냥","desc":"나물 입문을 원하는 편식쟁이에게 가장 무난한 선택지.","lines":[]},{"name":"콩","sub":"씨앗 3냥","desc":"그 무엇으로든 변할 수 있는 다재다능한 두류 식물.","lines":[]}]},{"id":"goblin","title":"도깨비 놀이","kind":"list","items":[{"name":"씨름","sub":"겨루는 스탯: 호전","desc":"승리 : 당신은 힘껏 커다란 장롱을 넘겼다. 장롱이 투덜거린다.\n패배 : 당신은 장롱에게 가볍게 넘겨졌다. 등이 흙으로 엉망이 된 모습에 도깨비들이 낄낄거린다.","lines":[]},{"name":"끝말잇기","sub":"겨루는 스탯: 호전","desc":"승리 : 당신은 낡은 사전과 한참 말씨름을 한 끝에 어떻게든 꼬투리를 잡아 보았다. 사전이 한 수 봐준 듯한 건 착각이겠지? \n패배 : 사람이 책을 어떻게 이겨? 도깨비는 친절한 말투로 김서방치고는 힘냈다고 위로해준다.","lines":[]},{"name":"술래잡기","sub":"겨루는 스탯: 신속","desc":"승리 : 당신은 바람처럼 달리던 수레바퀴를 잡아 멈춰 세웠다. 바퀴는 승부의 결과를 받아들였다.\n패배 : 당신은 빠르게 달려나가는 수레를 따라 달리다가, 흙먼지를 맞고 넘어지고 말았다. 다치진 않았지만 자존심이 상했다.","lines":[]},{"name":"숨바꼭질","sub":"겨루는 스탯: 안목","desc":"승리 : 당신은 돌부리 구석에 몸을 숨긴 낡은 숟가락을 간신히 찾아냈다. 숟가락이 펄쩍 뛰며 놀란다.\n패배 : 당신은 곳곳에 숨은 자그마한 물건들을 다 찾기는 커녕 하나도 간신히 발견해야 했다. 당신을 놀리듯 시간이 끝나자마자 여기저기서 작은 물건들이 튀어오른다.","lines":[]},{"name":"공기놀이","sub":"겨루는 스탯: 절제","desc":"승리 : 당신은 공깃돌을 제 수족처럼 다루며 승리를 따내었다. 어린 도깨비들은 승부도 잊고 신기하게 당신을 구경했다.\n패배 : 당신의 상대 도깨비는 공깃돌을 제 수족처럼 다루며 승리를 따내었다. 당신은 승부도 잊고 그것을 구경해야 했다.","lines":[]},{"name":"윷놀이","sub":"겨루는 스탯: 인내","desc":"승리 : 당신은 반칙이라며 주변에서 마구 구시렁대는 옷가지들을 무시하고 승리를 만끽한다.\n패배 : 당신의 승부 상대였던 천 옷가지들이 윷을 둘둘 감으며 승리를 만끽한다.","lines":[]}]},{"id":"psychics","title":"영능력","kind":"list","items":[{"name":"효험","sub":"","desc":"모두가 태어날 때부터 가지고 있는 영능력. 자신의 메인 턴에 앞서 켜 두면, 그 다음에 고르는 일반 공격·부적·영능력(생존본능·원숭이 손·도깨비불)이 자동으로 두 번 굴러 더 나은 쪽으로 들어간다.","lines":["토글을 켜도 턴을 쓰지 않는다. 실제로 공격을 고르는 순간 의지력 10(모자라면 0까지)이 들고, 토글은 그때 꺼진다. 도깨비불처럼 효과가 몇 턴 뒤에 터지는 영능력은, 걸어 둔 효험이 터지는 순간까지 그대로 유지된다.","처음부터 가지고 있다."]},{"name":"생존본능","sub":"","desc":"불리한 전투라고 판단이 될 때 적을 교란하고 전투에서 도망친다. 후일을 도모하는 것도 결국 살아있는 자들의 특권이 아닌가.","lines":["자신의 턴에 사용. (50+(신속*2)-상대의 영력)% 확률로 전투에서 도주한다.","전투 중 최초로 전투불능이 되어본다."]},{"name":"솜구름 안개","sub":"의지력 20","desc":"마치 구름처럼 희게 퍼지는 안개. 손끝으로부터 피어오른 안개는 적의 눈을 가리고 감정과 상태를 주무른다.","lines":["의지력 20 소모. 적의 다음 턴이 이미 정해져 있었다면(강공·영능력 등) 그걸 무르고 1d10을 다시 굴려 새로 정한다. 다시 굴린 결과가 똑같이 나왔을 경우에는 그냥 그대로 행한다.","(취득 경로 미정)"]},{"name":"형상 기억","sub":"","desc":"가장 안전하고 평화로웠던 기억을 떠올려 구현화시킨다. 돌아가고 싶어도 돌아갈 수 없다면 지금을 지켜!","lines":["의지력을 50만큼 소모한다. 자신 또는 일행 중 한 명의 체력을 무조건 100으로 회복시킨다.","(취득 경로 미정)"]},{"name":"내려쬐는 빛","sub":"의지력 10","desc":"스스로가 내뿜은 빛에 앞이 보이지 않는다. 이제 할 수 있는 것은 웅크리는 것뿐이다. 그러나 그것만으로도 충분하다.","lines":["쓸 때마다 의지력 10을 소모한다. 턴 제한 없이 아무 때나, 몇 번이든 다시 걸 수 있다. 단체 공격을 대신 맞으면 원래 맞았을 인원 수만큼 피해가 곱해진다. 사용한 직후 들어오는 그 공격은 무조건 '막기'로 처리된다(피해 감소 및 반격 포함).","(취득 경로 미정)"]},{"name":"원숭이 손","sub":"","desc":"얻는 만큼 잃는다. 영구적이게 얻고자 한다면 영구적이게 잃는다.","lines":["즉시 자신의 체력을 원하는 만큼 깎는다(체력은 0 이하로 내려갈 수 없다). 그 두 배만큼의 공격력을 일반 공격력에 더하고, 거기에 부적 1회치 피해를 더해 공격한다. 영능력 공격이라 안목 판정 없이 무조건 명중한다. 의지력은 깎은 체력에 10을 더한 만큼 소모한다. (석장 등 의지력 소비 감소 효과는 적용된다.) 사용 후 ((호전−인내)+(호전−절제))%의 확률로 즉시 행동불능이 되어 3턴 동안 아무 행동도 할 수 없다.","(취득 경로 미정 · 무구보관소 담당이 가지고 있다)"]},{"name":"도깨비불","sub":"의지력 20","desc":"어딘가에 홀연히 나타나는, 혼을 먹고 자라난다는 푸른 빛의 불꽃.","lines":["쓰는 즉시 의지력 20을 소모하고, 그 턴부터 3턴 동안 행동 불가 → 이어지는 턴에 자동으로 5배 공격. 영능력 공격이라 안목 판정 없이 무조건 명중한다. 전투·단체전투 모두에서 쓸 수 있다.","(취득 경로 미정)"]},{"name":"업인과보","sub":"의지력 10","desc":"원하지 않아도 업을 쌓을 수 있는 세계에서 ‘자신의 의지로’ 자신이 어떤 업을 쌓을지를 고를 수 있는 것은 행운이다.","lines":["의지력 10 소모. 전투 중 첫 턴에만 사용할 수 있으며, 대상을 지정할 수 있다. 사용 후 해당 전투에 나오는 [단체 공격], [2명 이상을 타겟팅하는 영능력]의 공격력이 모두 대상에게 단일로 향하며, 공격력은 인원 수만큼 곱해진다.","(취득 경로 미정 · 매점 담당이 가지고 있다)"]},{"name":"지신밟기","sub":"의지력 인내+50 (최대 99)","desc":"이곳은 절대적으로 안전하다. 거대한 무언가가 모두를 지켜주고 있다.","lines":["의지력 (인내+50, 최대 99) 소모. 첫 턴에만 사용할 수 있다. 전투가 끝날 때까지 아군 전원의 받는 피해가 인내/2% 감소한다.","(취득 경로 미정)"]},{"name":"벽사진경","sub":"의지력 선택한 의지력","desc":"사악한 것은 쫓아내고 복된 것은 맞이한다. 전투를 축제처럼 벌여 보자.","lines":["원하는 만큼 의지력을 사용해 지정한 일행 한 사람의 의지력을 그만큼 회복한다.","(취득 경로 미정)"]},{"name":"영력결계","sub":"의지력 0","desc":"볼 수 없다는 것은 축복이요, 볼 수 있다는 것은 저주라. 앎은 영혼을 얽매고 무지는 목을 조른다.","lines":["별도의 선언 없이 상시 발동. 일반 전투에서는 습득 시 적용되며, 보스 전투에서는 가져갈 영능력으로 선택했을 때만 적용된다. 적의 단일 영능력이 자신을 대상으로 하면 약공으로 대체된다. 단체 영능력은 그대로 발동하지만 자신에게만 효과가 없다. 대신 적 대상 영능력과 효험은 사용할 수 없으며, 자신·아군 대상 영능력은 사용할 수 있다.","(취득 경로 미정)"]},{"name":"칠성낙인","sub":"의지력 99","desc":"북두칠성의 기운을 새겨낸다. 그것은 마치 은하수처럼 흐르고, 폭포수처럼 쏟아진다.","lines":["의지력 99를 소모한다. 내가 직접 행동을 고르는 첫 번째 턴에만 쓸 수 있고(신속이 느려 상대가 먼저 움직였거나, 돌발 행동으로 몸이 먼저 나간 턴은 세지 않는다), 쓰면 전투 종료까지 장비 보정을 제외한 원래 호전 수치가 두 배가 된다.","(취득 경로 미정)"]},{"name":"언어장벽","sub":"의지력 20","desc":"인간도 짐승도 혼도 결국 태어나기 전 살았던 세계는 하나. 뜻이 통한다면 읽을 수 있으리.","lines":["의지력 20을 소모해 적의 앞으로 20턴을 먼저 간파한다. 드러난 20턴의 내용을 확인한 뒤, 바꿀 턴을 최대 세 개 골라 다시 굴린다. 몇 번째 라운드든, 일행 중 몇 번째 순서든 내 차례라면 언제든 쓸 수 있다. (간파는 턴을 쓰지 않고, 고른 턴을 확정할 때 내 턴이 끝난다.)","(취득 경로 미정)"]}]}]}]}}};
